(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c52"]=[{"id":"00009945","register_sub_id":"101","register_pk":"196092","name":"旧恩田重信家住宅土蔵","kana":"きゅうおんだしげのぶけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字竹山町1506","lat":36.55981408,"lng":138.19741627,"geo_status":"db","era":"江戸末期／安政2・明治5・明治43移築・平成23改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0439","desc":"主屋東側に南北棟で建つ。桁行五・五メートル梁間五・六メートル置屋根式の桟瓦葺で、西面に戸口を開き、下屋を設ける。小屋組は、両妻で折置組に、中央では京呂組とする。江戸末期に薬草栽培が奨励されたため、その薬草を納める蔵として建てられたと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009945"},{"id":"00009953","register_sub_id":"101","register_pk":"196100","name":"旧加藤家別荘","kana":"きゅうかとうけべっそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢下陣場895-13","lat":36.35286058,"lng":138.64241613,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建一部地階付、瓦葺、建築面積161㎡、煙突付","structure_material":"木造2階建一部地階付","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0447","desc":"木造二階建で、一階に居間、書斎、撞球室、食堂、台所及び女中室を、二階に寝室を配する。西面に上下階とも大きなガラス窓をたてて内側をサンルームとし、居間の北側に石積みの暖炉を設ける。軽井沢の別荘建築における木造モダニズムの先駆的な例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009953"},{"id":"00014242","register_sub_id":"101","register_pk":"509632","name":"旧加納家住宅主屋","kana":"きゅうかのうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字野沢原1212-16","lat":36.34963889,"lng":138.63146944,"geo_status":"db","era":"昭和25年／昭和40年移築","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積47㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"20 - 0603","desc":"旧軽井沢区六本辻の東に建つ坂倉準三設計の木造組立住宅。両妻面外側のＡの字形棟持柱で合成梁の棟を支えて切妻屋根を架け、その下に軸組を組む。内部の居間はロフト状の中二階を持ち、北側に水廻りや寝室を配する。戦後のプレファブ建築黎明期の希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014242"},{"id":"00009756","register_sub_id":"101","register_pk":"195585","name":"旧軽井沢ハウス(旧松方家別荘)","kana":"きゅうかるいざわはうす（きゅうまつかたけべっそう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字東裏地972","lat":36.35891822,"lng":138.63823931,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積135㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"20 － 0434","desc":"松方正義の孫である春子が所有していた別荘。木造二階建、切妻造鉄板葺で東面に下屋を設ける。外壁は赤色の下見板張で、各面に窓を配置する。内部は上下階とも中廊下の両側に部屋を配し、一階居間には浅間石の暖炉を築く。開放的で落着いた佇まいの別荘。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009756"},{"id":"00012904","register_sub_id":"101","register_pk":"368007","name":"旧北澤家住宅主屋","kana":"きゅうきたざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県大町市八坂908","lat":36.48641111,"lng":137.90394722,"geo_status":"db","era":"嘉永2年（1849）頃／明治後期・昭和50年代改修","year":1849,"year_source":"db","year_min":1849,"year_max":1849,"year_label":null,"structure":"木造平屋一部2階建、茅葺（金属板仮葺）、建築面積365㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"20 － 541","desc":"市東部の山間にある集落の庄屋宅。間口の広い寄棟造茅葺（鉄板仮葺）の二階建、軒出桁造で、南正面の東寄りに玄関、二階中央に縁を出す。西に土間、東に4列に室を並べ、土間に重厚な梁組を現し、東端列奧を上質な座敷とする。山村景観の核をなす豪壮な民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012904"},{"id":"00014380","register_sub_id":"101","register_pk":"511369","name":"旧喜多屋新井家住宅東蔵","kana":"きゅうきたやあらいけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上伊那郡宮田村3285-18","lat":35.76929722,"lng":137.94148611,"geo_status":"db","era":"江戸後期／天保14年(1843)増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0625","desc":"主屋東側に西面し、穀類や家財を収納する土蔵。二階建切妻造平入南北棟の二棟の土蔵を接続し、北側の通路部を含んで、桟瓦葺屋根を架ける。外壁は漆喰仕上で腰は海鼠壁とし、内部一階は三室、二階は二室とする。通路東面に門を開き、敷地東辺を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014380"},{"id":"00003535","register_sub_id":"101","register_pk":"104525","name":"旧越家住宅内蔵","kana":"きゅうこしけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂435-2他","lat":36.656952,"lng":138.31262769,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0139","desc":"南北棟の切妻造，平入，２階建の土蔵で，基礎は当地方によく見られる玉石を丁寧に積んだ石積とし，壁は荒壁仕上，屋根は桟瓦葺，置屋根形式で，妻を壁で塞ぐ。正面は重厚な観音扉をつけ，蔵前の部屋を介して主屋の西端と連続し，敷地後方の構えを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003535"},{"id":"00003534","register_sub_id":"101","register_pk":"104524","name":"旧越家住宅主屋","kana":"きゅうこしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂435-2他","lat":36.656948,"lng":138.31280183,"geo_status":"db","era":"明治中期／明治末期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積280㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0138","desc":"東を通る街路沿いに屋敷を構える。東西に細長い南面する桟瓦葺の建物で，東側の２階建部分と入母屋造の中央平屋建部が古く，さらに西側の切妻造部分が増築になる。街路側に東妻面を向け，白漆喰塗で変化に富む外観は，製糸業で繁栄した往時をよく偲ばせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003534"},{"id":"00003536","register_sub_id":"101","register_pk":"104526","name":"旧越家住宅外蔵","kana":"きゅうこしけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂435-2他","lat":36.65686872,"lng":138.31262769,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0140","desc":"主屋の南西に建つ。南北棟の切妻造，桟瓦葺，平入，２階建の土蔵で，東面に蔵前庇をつけ，２階窓には鉄格子を入れる。基礎は当地方に多く見られる玉石積で，壁は白漆喰塗だが，腰を鉄板で覆う。外観は簡素であるが，敷地後方の構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003536"},{"id":"00015187","register_sub_id":"101","register_pk":"530611","name":"旧櫻井家住宅店舗兼主屋","kana":"きゅうさくらいけじゅうたくてんぽけんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県大町市大町3286-4","lat":36.50395278,"lng":137.86064444,"geo_status":"db","era":"明治26年頃／昭和前期・同後期・平成2年・同30年改修","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積199㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0663","desc":"大町市の中心部、糸魚川街道に北面して建つ旧塩問屋の町家。２階建切妻造平入瓦葺で、正面二階は柱と貫を現して袖壁を付す。内部は２列７室を配し、南西に十二畳の床構え付きの座敷を配す。妻面を柱形を現して漆喰で塗込め、明治22年大火後の復興を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015187"},{"id":"00015188","register_sub_id":"101","register_pk":"530612","name":"旧櫻井家住宅土蔵","kana":"きゅうさくらいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県大町市大町3286-4","lat":36.50374722,"lng":137.86068889,"geo_status":"db","era":"明治12年／昭和後期改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0664","desc":"主屋の背後に位置し、北面して建つ家財蔵。二階建切妻造妻入、置屋根形式で、外壁漆喰塗とし、一階正面戸口と二階窓に掛子塗扉を吊る。内部は各階一室の板敷とし、中央の独立柱で棟木を支持し垂木を架ける。軸部木太く、明治二二年大火前に遡る貴重な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015188"},{"id":"00005845","register_sub_id":"101","register_pk":"106831","name":"旧真田勘解由家住宅主屋","kana":"きゅうさなだかげゆけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代212-1他","lat":36.562187,"lng":138.195877,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積296㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0271","desc":"松代城下武家町の北東角地に敷地を構える。敷地中央に建つ木造つし２階建，寄棟造，桟瓦葺で，北面中央に入母屋造の玄関がつく。桁行１１間，梁間４間で，東を土間とし，座敷１２．５畳を中心とした居室の周囲に縁が巡る。上級武家住宅の風格を示す遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005845"},{"id":"00005846","register_sub_id":"101","register_pk":"106832","name":"旧真田勘解由家住宅鎮守社","kana":"きゅうさなだかげゆけじゅうたくちんじゅしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代212-1","lat":36.562317,"lng":138.196014,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積5㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0272","desc":"主屋の北東方に南面して建つ。桁行１間，梁間１間半，切妻造，桟瓦葺の平入とし，大棟を輪違いに積む。内部は畳敷で奥に祭壇を設け，家祖昌幸を祀る社殿２社等を祀る。外壁は真壁造の白漆喰仕上げで，腰を海鼠壁としている。正面は両開格子戸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005846"},{"id":"00012151","register_sub_id":"101","register_pk":"352950","name":"旧ジョルゲンセン邸","kana":"きゅうじょるげんせんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字上陣場902-9","lat":36.35459,"lng":138.639472,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、金属板葺、建築面積75㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"20-522","desc":"アメリカ人宣教師ジョルゲンセンが所有した別荘。木造二階建、切妻造で、寄棟造の張出し部にサンルームを兼ねた玄関を設ける。一階の中心は食堂兼リビングで石積の暖炉を築く。二階は寝室で建具がよく残る。外壁は下見板張で、各面に窓を開き開放的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012151"},{"id":"00003427","register_sub_id":"101","register_pk":"104417","name":"旧高橋家住宅北蔵","kana":"きゅうたかはしけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市穂高北穂高626-12","lat":36.35506801,"lng":137.89103397,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積65㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0134","desc":"西蔵の北側に接して建ち，西蔵側を正面とする。桁行３間，梁間１間半の土蔵造２階建で，正面には１間幅の下屋をかけ，一部を室内としていた時期もあったが，最近の修理で撤去している。屋根は桟瓦葺で，置屋根型式。敷地の西北隅を画する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003427"},{"id":"00003424","register_sub_id":"101","register_pk":"104414","name":"旧高橋家住宅主屋","kana":"きゅうたかはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市穂高北穂高626-12","lat":36.35506342,"lng":137.89129472,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積143㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0131","desc":"豪農として栄え，近代に入っては北穂高村長も務めた家柄の住居。江戸中期の創建と伝えられ，増改築を経て今日に至るが，近年の解体修理で主要部が完成した時点の姿に復原された。穂高地方の近世から近代にかけての農家建築の残存例のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003424"},{"id":"00003426","register_sub_id":"101","register_pk":"104416","name":"旧高橋家住宅西蔵","kana":"きゅうたかはしけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市穂高北穂高626-12","lat":36.35498808,"lng":137.89107472,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0133","desc":"主屋の西側に建ち，主屋側を正面として扉口を開く。桁行４間，梁間２間の土蔵造２階建で，平入とする。正面側には全幅にわたって柱の出約５尺の庇をかける。現在収蔵庫として活用されており，近世から近代にかけての農村景観を今日に伝える建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003426"},{"id":"00003425","register_sub_id":"101","register_pk":"104415","name":"旧高橋家住宅南蔵","kana":"きゅうたかはしけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市穂高北穂高626-12","lat":36.35489699,"lng":137.89139914,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0132","desc":"主屋の南方に建つ切妻造，桟瓦葺の土蔵。主屋側に庇をかけ扉口２カ所を設ける。腰部は海鼠壁。１階は１０畳の座敷と板間で，２階は１室とするが，当初は１階も１室であったと思われる。墨書より明治３６年の建築であることが判明している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003425"},{"id":"00006243","register_sub_id":"101","register_pk":"107227","name":"旧田中角榮家別荘","kana":"きゅうたなかかくえいけべっそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢1331-7","lat":36.36312035,"lng":138.62432507,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"20 － 0313","desc":"水戸徳川家１３代当主徳川圀順の軽井沢別荘として建設。木造２階建，フランス瓦葺，総下見板張の洋風別荘建築で，北東部に尖塔を置き，四面に妻破風を見せ，玄関部に石を積むなどピクチャレスクな外観を呈する。住宅専門会社あめりか屋の設計力量を示す作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006243"},{"id":"00016382","register_sub_id":"101","register_pk":"536449","name":"旧土屋家住宅主屋","kana":"きゅうつちやけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市下室賀2770-1","lat":36.40233333,"lng":138.16189444,"geo_status":"db","era":"明治25年／昭和中期改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、茅葺（鉄板仮葺）、建築面積116㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0676","desc":"市街地北西の山間に位置しかつて養蚕を営んだ農家の主屋。敷地東側に西面して建つ二階建寄棟造茅葺(鉄板仮葺)。一階は正面北寄に玄関土間、南東角に座敷を配す。二階は三室の板間を南北に並べ蚕室とする。二階正面に大きな窓を並べ、養蚕農家らしい外観の民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016382"},{"id":"00012152","register_sub_id":"101","register_pk":"352951","name":"旧西川家住宅","kana":"きゅうにしかわけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字上陣場902-13","lat":36.354467,"lng":138.63962,"geo_status":"db","era":"昭和初期／昭和57年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、金属板葺、建築面積69㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"20-523","desc":"ヴォーリズ建築事務所による別荘建築。木造二階建、下見板張、切妻造で、下屋庇を付ける。一階は居間や台所で、二階は廊下を挟んで寝台を造り付けた寝室と地袋付の八畳和室を配す。小規模ながら、収納家具などに生活への配慮が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012152"},{"id":"00010782","register_sub_id":"101","register_pk":"201617","name":"旧ハミルトンアンドハード軽井沢コテージ","kana":"きゅうはみるとんあんどはーどかるいざわこてーじ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字高瀬愛宕山1342-75","lat":36.365171,"lng":138.634646,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積68㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0494","desc":"旧軽井沢地域に所在する、ヴォーリズ設計の別荘建築。木造二階建、半切妻屋根で、外壁は下見板張、内部も板壁を基本とする比較的簡素な内外観であるが、水平の連続窓や石積みの煙突、室内の作り付けの調度類などに、ヴォーリズの別荘建築らしい特徴が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010782"},{"id":"00013109","register_sub_id":"101","register_pk":"368267","name":"旧平林家住宅（一星亭）主屋","kana":"きゅうひらばやしけじゅうたく（いちぼしてい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県東筑摩郡生坂村5497","lat":36.42415556,"lng":137.92784444,"geo_status":"db","era":"江戸後期／明治前期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積354㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0554","desc":"旧道沿いの敷地中央に南面して建つ二階建。三列構成の床上部は数室を食違いに並べる複雑な平面として上手に座敷を配する。土間上部を広い作業場とし、東妻を兜屋根状に切上げ、棟上に長い越屋根を設けるなど、当地で盛行した煙草生産の名残を留める大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013109"},{"id":"00013111","register_sub_id":"101","register_pk":"368269","name":"旧平林家住宅（一星亭）西土蔵","kana":"きゅうひらばやしけじゅうたく（いちぼしてい）にしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県東筑摩郡生坂村5497","lat":36.42428056,"lng":137.92775,"geo_status":"db","era":"安政3年（1856）","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡、北門付","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0556","desc":"主屋北背面で東土蔵と並び建つ。東西棟、土蔵造二階建、切妻造桟瓦葺。外壁漆喰塗で軒裏まで塗込める。南面の中央と東端に戸口を設け、いずれも木瓜形の縁取りを施した土戸を片引に立てる。敷地内で最大の土蔵で、東土蔵とともに重厚な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013111"},{"id":"00013110","register_sub_id":"101","register_pk":"368268","name":"旧平林家住宅（一星亭）東土蔵","kana":"きゅうひらばやしけじゅうたく（いちぼしてい）ひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県東筑摩郡生坂村5497","lat":36.42426389,"lng":137.9279,"geo_status":"db","era":"天保11年（1840）","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0555","desc":"主屋北背面で西土蔵と並び建つ。東西棟、土蔵造二階建、切妻造桟瓦葺である。外壁漆喰塗で、腰を海鼠壁とする。南面に戸口を設けて掛子塗の土戸を両開きとし、扉には木瓜形の縁取りなどを丁寧な左官仕事で造る。敷地内最古の土蔵で旧道沿いの景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013110"},{"id":"00013112","register_sub_id":"101","register_pk":"368270","name":"旧平林家住宅（一星亭）南土蔵","kana":"きゅうひらばやしけじゅうたく（いちぼしてい）みなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県東筑摩郡生坂村5497","lat":36.42406667,"lng":137.92766111,"geo_status":"db","era":"安政6年（1859）／平成20年代改修","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡、塀付","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0557","desc":"主屋南西側に南北棟で建つ、土蔵造二階建、切妻造桟瓦葺。外壁漆喰塗で、腰は木瓜形の縁取りの内方を黒漆喰塗とし、上部は軒裏まで塗込める。東面の戸口は鳥居形の扉枠を設け、対向面を海鼠壁で養生する。主屋とともに往時の屋敷構えを伝える幕末の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013112"},{"id":"00013114","register_sub_id":"101","register_pk":"368272","name":"旧平林家住宅（一星亭）南門","kana":"きゅうひらばやしけじゅうたく（いちぼしてい）みなみもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県東筑摩郡生坂村5497","lat":36.42424722,"lng":137.92814167,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口1.6m、左右袖塀付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0559","desc":"主屋南東隅から東に延びる間口四間の門塀。腕木で切妻造桟瓦葺屋根を支持する。中央西間を間口一・六メートルの門口としてケヤキ製の上質な板戸を開く。門口の両脇間は真壁漆喰塗で、上方に木瓜形の木枠に格子を組んだ窓を穿つ。瀟洒な趣を備えた門塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013114"},{"id":"00013113","register_sub_id":"101","register_pk":"368271","name":"旧平林家住宅（一星亭）物置","kana":"きゅうひらばやしけじゅうたく（いちぼしてい）ものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県東筑摩郡生坂村5497","lat":36.424075,"lng":137.92802778,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0558","desc":"敷地東辺北端に南北棟で建つ木造平屋建、切妻造桟瓦葺。主屋に面する西面を吹放し、残る三面は外部を真壁土塗りとする。村道に面する東面の南寄りに出入口を設けて板戸両開きとし、物資搬出入を可能とする。往時の暮らしぶりを伝え、屋敷構えを形成する施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013113"},{"id":"00005868","register_sub_id":"101","register_pk":"106854","name":"旧三河屋商店倉庫","kana":"きゅうみかわやしょうてんそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市大字長野東町165-3","lat":36.65577877,"lng":138.18872977,"geo_status":"db","era":"江戸後期／平成8曳家","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0263","desc":"味噌蔵の奥に並んで建つ土蔵造平屋建である。当初は桁行８間，梁間２間であったが，移築時に桁行を４間に切り縮めている。屋根は切妻造，桟瓦葺で平入とし，正面に瓦葺の土庇をつけて戸口を設け，引戸を建て込む。外壁は白漆喰塗で，正面側の腰を海鼠壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005868"},{"id":"00005850","register_sub_id":"101","register_pk":"106836","name":"旧三河屋商店土蔵","kana":"きゅうみかわやしょうてんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字長野東町165-3","lat":36.655647,"lng":138.1890474,"geo_status":"db","era":"江戸後期／平成8曳家","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0261","desc":"主屋の背後に位置する土蔵造２階建で，桁行３間半，梁間２間半の平入である。屋根は切妻造，桟瓦葺で，正面に瓦葺の土庇をつけ戸口を開き，黒漆喰仕上げの両開き塗戸を釣り込む。外壁は白漆喰塗とし，２階の正面中央には黒漆喰仕上げの両開き塗戸付の窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005850"},{"id":"00005857","register_sub_id":"101","register_pk":"106843","name":"旧三河屋商店味噌蔵","kana":"きゅうみかわやしょうてんみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字長野東町165-3","lat":36.65575305,"lng":138.18888966,"geo_status":"db","era":"江戸後期／平成8曳家","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0262","desc":"主屋の背後に土蔵と向かい合って建つ。土蔵造２階建で，桁行２間半，梁間２間の平入である。屋根は切妻造，桟瓦葺で，正面に瓦葺の土庇をつけて戸口を設け，引戸を建て込む。外壁は白漆喰塗で，正面側の腰を海鼠壁とする。小規模であるが，左官技術は高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005857"},{"id":"00010595","register_sub_id":"101","register_pk":"201169","name":"旧彌永家別荘","kana":"きゅうやながけべっそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字東卯ツ木原288-5","lat":36.359083,"lng":138.631775,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積109㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"20－0486","desc":"旧軽井沢別荘地内の敷地中央に建つ。木造二階建で東正面に切妻屋根の玄関を構え、南面に配する広いサンルームを下屋として張り出す。外壁下見板張で妻壁の束を意匠的に見せる。平面は、玉石積の暖炉を備えたダイニングを中心に各室を配する。瀟洒な別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010595"},{"id":"00011306","register_sub_id":"101","register_pk":"209143","name":"旧山田家住宅裏門・台所味噌蔵及び事務所","kana":"きゅうやまだけじゅうたくうらもん・だいどころみそぐらおよびじむしょ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県中野市大字江部字長井田46-3","lat":36.736133,"lng":138.34524,"geo_status":"db","era":"明治13頃","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積87㎡","structure_material":"木造平屋一部2階建","registered":"2016.11.29(平成28.11.29)","register_no":"20－0506","desc":"質蔵及び文庫蔵と連続して敷地北辺を画す建物。東から、台所味噌蔵、事務所、裏門の順に続く。事務所は内装を洋風意匠とする。裏門は、ケヤキを用いて重厚な構えを見せ、事務所等とともに北面を土蔵のように白漆喰塗の大壁造として、一連の景観を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011306"},{"id":"00011303","register_sub_id":"101","register_pk":"209140","name":"旧山田家住宅奥座敷","kana":"きゅうやまだけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県中野市大字江部字長井田46-3","lat":36.73616627,"lng":138.34564435,"geo_status":"db","era":"明治中期／昭和26頃移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"20－0503","desc":"敷地中央に位置し、庭に面して建つ。二室の続き座敷で、東面に床と棚を設け、西面に押入を設ける。床柱はスギの絞り丸太で、書院は平書院とし、良材を用いてすっきりとした座敷飾りを見せる。南北両側に縁を設け、明るく開放的なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011303"},{"id":"00011309","register_sub_id":"101","register_pk":"209146","name":"旧山田家住宅酒売場","kana":"きゅうやまだけじゅうたくさけうりば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県中野市大字江部字長井田46-3","lat":36.73571,"lng":138.345289,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積128㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"20－0509","desc":"敷地の西辺、二間蔵の南端に接して南北棟で建つ。大正元年まで酒造を行っており、その売場として建てられた。戦前期までは蚕室として、その後には倉庫等に用いられた。外壁を塗込める旧山田家の外構建物群にあって、唯一、真壁造として変化を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011309"},{"id":"00011305","register_sub_id":"101","register_pk":"209142","name":"旧山田家住宅質蔵及び文庫蔵","kana":"きゅうやまだけじゅうたくしちぐらおよびぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県中野市大字江部字長井田46-3","lat":36.736214,"lng":138.345371,"geo_status":"db","era":"弘化5","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積76㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"20－0505","desc":"通りに面した敷地北辺を画す二階建の土蔵。東の質蔵と西の文庫蔵の二棟の土蔵に、一体の置屋根と、敷地内側に蔵前部分の庇を連続して架けた構造とする。防火に配慮して、善光寺地震再興時に建設された土蔵で、白漆喰の壁と腰下見板張が通りの景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011305"},{"id":"00011304","register_sub_id":"101","register_pk":"209141","name":"旧山田家住宅新座敷","kana":"きゅうやまだけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"長野県","address":"長野県中野市大字江部字長井田46-3","lat":36.73601,"lng":138.345626,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"20－0504","desc":"敷地中央に奥座敷と矩折れに接続して建つ。起りをつけた桟瓦葺屋根を持つ。北側で玄関と接続しており、四畳の取次を経て八畳の客間に入る構成を取る。客間では奇木を落掛に用いたり、小壁に格狭間風の窓を開けるなど、数寄屋意匠を取り入れた座敷となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011304"},{"id":"00011307","register_sub_id":"101","register_pk":"209144","name":"旧山田家住宅隅蔵","kana":"きゅうやまだけじゅうたくすみのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県中野市大字江部字長井田46-3","lat":36.736062,"lng":138.34508,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積54㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"20－0507","desc":"裏門と連続して、敷地の北西隅に建つ土蔵。南に出入口を設けた東西棟とし、建ちの高い平屋建で、内部は壁、床とも板張りで仕上げる。置屋根形式で裏門と一連に桟瓦を葺いており、敷地北面及び西面の一連の建物とともに街路側の景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011307"},{"id":"00011308","register_sub_id":"101","register_pk":"209145","name":"旧山田家住宅六間蔵及び二間蔵","kana":"きゅうやまだけじゅうたくろっけんぐらおよびにけんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県中野市大字江部字長井田46-3","lat":36.735921,"lng":138.345158,"geo_status":"db","era":"明治13頃","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積139㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"20－0508","desc":"敷地の西辺、隅蔵と酒売場の間に南北棟で建つ土蔵。穀蔵などとして用いられていた蔵で、建ちの高い平屋を基本としながら、一部に二階床を張る。桁行二六メートルの長大な土蔵に一連で屋根を架け、敷地内側に三ヵ所の出入口を設けて、敷地景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011308"},{"id":"00009942","register_sub_id":"101","register_pk":"196089","name":"旧山寺常山家住宅表門","kana":"きゅうやまでらじょうざんけじゅうたくおもてもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字竹山町1493-1","lat":36.55766207,"lng":138.19720324,"geo_status":"db","era":"江戸末期／平成16改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0436","desc":"屋敷地の東側を区画する長大な長屋門で、桁行二三メートルを測る。中央の門は間口二・一メートルで、門の左右に出格子や与力窓を設け、前面の腰に下見板を張る。武家屋敷の正面構えに相応しい風格をもつ表門で、地域の街路景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009942"},{"id":"00009941","register_sub_id":"101","register_pk":"196088","name":"旧山寺常山家住宅書院","kana":"きゅうやまでらじょうざんけじゅうたくしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市松代町松代字竹山町1493-1","lat":36.55747295,"lng":138.19720551,"geo_status":"db","era":"大正後期／平成16改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0435","desc":"象山の東麓、松代城下の南西端に位置する。庭園への眺望を意識して、床面の高い構成とする。東西二列に計六室を配し、庭に面する東列に座敷を並べて東南面に縁を廻し、西列の北端室を円窓を持つ茶室とする。座敷飾や茶室の意匠に趣向を凝らした開放的な書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009941"},{"id":"00009943","register_sub_id":"101","register_pk":"196090","name":"旧山寺常山家住宅頌徳門","kana":"きゅうやまでらじょうざんけじゅうたくしょうとくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代字竹山町1493-1","lat":36.55782301,"lng":138.197174,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造、瓦葺、間口1.9m、左右袖塀付","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0437","desc":"屋敷地の北東端に東面して建つ。間口一・九メートルの棟門で、切妻造桟瓦葺とし、左右の袖塀と背面に控柱がつく。大正末期に主屋が失われた後、敷地北側に頌徳碑が建てられ、その表門として建てられた。松代城下の通りに面して、歴史的な佇まいを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009943"},{"id":"00009755","register_sub_id":"101","register_pk":"195584","name":"旧ライシャワー家別荘","kana":"きゅうらいしゃわーけべっそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字林ノ根1004-34","lat":36.35978672,"lng":138.64408564,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、鉄板葺、建築面積74㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"20 － 0433","desc":"オーガスト・Ｋ・ライシャワーが営んだ別荘。木造二階建、入母屋造鉄板葺で、外壁は杉皮張とする。内部は軸部に丸太を使い、壁も杉皮張や竹網代張とし、浅間石積の暖炉を築くなど、野趣豊かな構成である。通風や採光にも配慮され、軽井沢の別荘の一典型を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009755"},{"id":"00014603","register_sub_id":"101","register_pk":"515145","name":"旧ロミッシー別荘（一柳家別邸）","kana":"きゅうろみっしーべっそうひとつやなぎけべってい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字下森外887-33","lat":36.35446111,"lng":138.63753333,"geo_status":"db","era":"大正12年／令和2年移築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積110㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"20 - 0631","desc":"万平通り北側の別荘地に建つ木造二階建。内部は中廊下と階段室の周囲に各室を並べる独立性高い間取り。一階居間に暖炉を設け、正面に玄関と二階テラスを張り出す。外観は下見板張や鎧戸付窓等で洋風とし、テラス菱組天井がコロニアル要素も示す大正期の別荘。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014603"},{"id":"00014823","register_sub_id":"101","register_pk":"519081","name":"京口屋墨矢家住宅主屋","kana":"きょうぐちやすみやけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上伊那郡宮田村3303","lat":35.76721389,"lng":137.94144722,"geo_status":"db","era":"明治23年頃／昭和40年代改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積89㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0645","desc":"伊那街道の宮田宿に所在するかつて料理屋を営んだ町家。街道に西面する二階建切妻造平入で前面に下屋を設け、棟に越屋根を付す。内部は南に土間、北に居室一列を配す。二階前面に座敷二室を並べ、縁の手摺に松葉形の飾りをあしらい、宿場の風情を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014823"},{"id":"00005852","register_sub_id":"101","register_pk":"106838","name":"杭全家住宅土蔵","kana":"くまたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代635","lat":36.565189,"lng":138.202194,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0275","desc":"東西に長い敷地の北東隅に位置する。桁行３間半，梁間２間半の土蔵造２階建で，切妻造，桟瓦葺の東西棟である。切石基礎上に建ち，外壁は中塗仕上げとする。西妻に鉄板葺の庇をつけて戸口を設け，両開の塗戸を釣り込む。２階の西面と南面に両開窓を開いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005852"},{"id":"00005152","register_sub_id":"101","register_pk":"106142","name":"倉澤家住宅長屋門","kana":"くらさわけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代1351-10","lat":36.55949566,"lng":138.20109341,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0220","desc":"南北棟の切妻造，平屋建，桟瓦葺で，南半に門口を構え，北半を倉庫とする。門口は中央部に扉を吊り，南端を潜戸とし，倉庫東面に出格子をつける。柱から扉板まで欅材を用いた丁寧なつくり。街路沿いにあって，往時の武家屋敷の表構えを今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005152"},{"id":"00014375","register_sub_id":"101","register_pk":"511364","name":"栗林家住宅（創舎わちがい）主屋","kana":"くりばやしけじゅうたく（そうしゃわちがい）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県大町市大町4084-1他","lat":36.50513611,"lng":137.85898889,"geo_status":"db","era":"江戸末期／明治前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺及び鉄板葺、建築面積119㎡","structure_material":"木造平屋一部2階建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0620","desc":"大町市街地の町方庄屋の住居。通りから門、庭を前面に介して位置し、南側の店舗側面後方と接続する。切妻造平入で元は板葺。壁は真壁造漆喰仕上。庭に面して床構え付続き座敷、背面側に家人用座敷を並べる。近代以降も町の要職を務めた旧家の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014375"},{"id":"00014376","register_sub_id":"101","register_pk":"511365","name":"栗林家住宅（創舎わちがい）門及び塀","kana":"くりばやしけじゅうたく（そうしゃわちがい）もんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県大町市大町4084-1他","lat":36.50519444,"lng":137.85913611,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.6m、板塀付、総延長8.9m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0621","desc":"大町市街中心部に所在する町方庄屋の屋敷の門。店舗の北に並んで通りに開き、庭を介して主屋へ導く。切妻造桟瓦葺の薬医門で、北側袖壁に潜り戸を設け、桟瓦葺板塀が連なる。店舗との間も板塀で塞ぐ。装飾は殆ど無いが、格式有る構えで歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014376"},{"id":"00008988","register_sub_id":"101","register_pk":"162348","name":"小口家別邸主屋","kana":"こぐちけべっていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県岡谷市銀座2-6525","lat":36.06733255,"lng":138.05404586,"geo_status":"db","era":"大正前期／昭和50年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建一部2階建、瓦葺、建築面積231㎡、門付","structure_material":"木造平屋建一部2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0385","desc":"敷地中央に建ち、木造一部二階建、建築面積２３１㎡、桟瓦葺で、正面南寄りに中門を構える。緩勾配の切妻造妻入で、伝統的な本棟造の外観構成とするが、起りのある切妻屋根の客用玄関を構えるなど豪華なつくりで、近代岡谷の製糸業の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008988"},{"id":"00008989","register_sub_id":"101","register_pk":"162349","name":"小口家別邸土蔵","kana":"こぐちけべっていどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県岡谷市銀座2-6525","lat":36.06739441,"lng":138.05392451,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵2階建、瓦葺、建築面積66㎡、門付","structure_material":"土蔵2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0386","desc":"敷地の西寄り、主屋北側に東西棟で建ち、桁行７．３ｍ梁間４．５ｍ、土蔵造二階建、切妻造桟瓦葺である。主屋のある南面に出入口を開き、左脇に小窓を穿つ。外壁は漆喰塗で腰を簓子下見板張とする。伝統的な屋敷構えを構成する土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008989"},{"id":"00013099","register_sub_id":"101","register_pk":"368370","name":"小坂家住宅裏倉庫","kana":"こさかけじゅうたくうらそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字村山字市ノ口282","lat":36.66131111,"lng":138.26411944,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0544","desc":"敷地北辺の東寄り、主屋土間部の後方に東西棟で建つ。土蔵造二階建、切妻造、置屋根形式の桟瓦葺で、西妻の戸口に下屋を設ける。外壁漆喰塗で鉢巻を廻らし、腰を簓子下見板とする。東に連なる裏門、農機具庫とともに敷地背面側の落着いた佇まいを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013099"},{"id":"00013103","register_sub_id":"101","register_pk":"368374","name":"小坂家住宅裏門","kana":"こさかけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字村山字市ノ口282","lat":36.66131667,"lng":138.26418056,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0548","desc":"敷地北辺、農機具庫と裏倉庫の間を繋ぐように設けた門。東の農機具庫寄りに、一間腕木門形式で切妻造の門を建て、西側の裏倉庫との間を竪板張の袖塀でふさぐ。門は腕木で軒桁を受け、垂木を使わず化粧裏板張のうえ桟瓦を葺く。往時の生活様態を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013103"},{"id":"00013098","register_sub_id":"101","register_pk":"368369","name":"小坂家住宅米蔵","kana":"こさかけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字村山字市ノ口282","lat":36.66105,"lng":138.26375833,"geo_status":"db","era":"安政2年（1855）","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造平屋一部2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0543","desc":"敷地南西隅に南北棟で建つ。土蔵造一部二階建、切妻造、置屋根形式の桟瓦葺で、東面中央の戸口に吹放しの下屋を付す。外壁は中塗で鉢巻や戸口、窓廻りを漆喰で仕上げる。内部は壁を板張とする。旧家の屋敷構えを引立てる幕末の大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013098"},{"id":"00013097","register_sub_id":"101","register_pk":"368368","name":"小坂家住宅主屋","kana":"こさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字村山字市ノ口282","lat":36.66119722,"lng":138.26405556,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積226㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0542","desc":"千曲川左岸の敷地中央に南面して建つ。寄棟造茅葺の棟に茅葺の越屋根を載せる。東寄りを土間とし、床上部は三列構成で上手列に座敷二室を前後に並べる。土間回りは重厚な柱梁を現し、座敷の造作も良好に保存する。北信地方民家の特徴を示す大型住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013097"},{"id":"00013104","register_sub_id":"101","register_pk":"368375","name":"小坂家住宅土塀","kana":"こさかけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字村山字市ノ口282他","lat":36.66133611,"lng":138.26376389,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長58m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0549","desc":"敷地南西隅の米蔵から北辺東寄りの裏倉庫まで矩折れに廻らし北・西面を画す土塀で、両端に片開戸を開く。土台上の柱から腕木を出して軒桁を受け、化粧裏板を張り桟瓦を葺く。西面塀外壁は大壁で腰を簓子下見板、北面塀は真壁とする。農村景観に寄与する土塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013104"},{"id":"00013102","register_sub_id":"101","register_pk":"368373","name":"小坂家住宅長屋門","kana":"こさかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字村山字市ノ口282","lat":36.661125,"lng":138.26426667,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積127㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0547","desc":"敷地東辺中央に構える長屋門。切妻造桟瓦葺で、北側に延びる塀の敷地内側を切妻造屋根で吹放しの物置とする。外壁は真壁で腰を簓子下見板とし、中央南寄りの門口は成の高い冠木に二重梁を架け、重厚なつくりである。屋敷の表構えに風格を添える大型の長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013102"},{"id":"00013100","register_sub_id":"101","register_pk":"368371","name":"小坂家住宅農機具庫","kana":"こさかけじゅうたくのうきぐこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字村山字市ノ口282","lat":36.66130556,"lng":138.26424167,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造平屋一部2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0545","desc":"敷地北東隅に東西棟で建つ。土蔵造一部二階建、切妻造桟瓦葺で、南面に戸口を開き、吹放しの下屋を設ける。敷地内で唯一、外壁を軒裏まで塗込める建物で、腰は簓子下見板。鬼門除けのためか北・東面は無窓で、北東隅を隅切とする。屋敷構えを特徴付ける土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013100"},{"id":"00013101","register_sub_id":"101","register_pk":"368372","name":"小坂家住宅味噌蔵","kana":"こさかけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字村山字市ノ口282","lat":36.66102222,"lng":138.26425556,"geo_status":"db","era":"明治前期／平成18年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0546","desc":"敷地南東隅に東西棟で建つ。土蔵造二階建、切妻造桟瓦葺で、北面東寄りの物置が長屋門の南端に接続する。北面西寄りの下屋に戸口を開く。外壁は中塗で腰を簓子下見板とし、二階三面に小窓を穿ち東西面に庇を付す。長屋門と一体の外観で重厚な表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013101"},{"id":"00001819","register_sub_id":"101","register_pk":"102809","name":"児玉家住宅馬屋","kana":"こだまけじゅうたくうまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県東御市大字和7785","lat":36.3795218,"lng":138.33282738,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0080","desc":"蚕室の東妻面に張り出した間口２間，奥行４間の下屋部分で，大壁造の東面と北面は裏の畑地や竹林に面し，東南端で東門に取付く屋根付土塀に接続する。乗馬用の馬屋であり，簡素ながら隠居分家した児玉分家の繁栄振りをうかがうことのできる施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001819"},{"id":"00001820","register_sub_id":"101","register_pk":"102810","name":"児玉家住宅表門","kana":"こだまけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.3791199,"lng":138.3326658,"geo_status":"db","era":"明治34頃","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造、瓦葺、間口7.5m、8.9m及び3.6m袖塀付","structure_material":"木造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0083","desc":"松代禰津往還道からややひいた位置に建つ。桟瓦葺，切妻造の３間四脚門で，両脇間に潜戸を設ける。扉の鏡板をケヤキの１枚板とするなど上質な造りになる。亀甲積の石垣，隅櫓風の土蔵とあいまって豪農屋敷の理想的構えとされた城郭風の構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001820"},{"id":"00001816","register_sub_id":"101","register_pk":"102806","name":"児玉家住宅北塀","kana":"こだまけじゅうたくきたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.37940547,"lng":138.33243889,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、延長37m","structure_material":"木造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0088","desc":"敷地の西北辺を限る塀で，西塀の北妻面に発し，６間分の地点で東方に折れて蚕室西南端の裏口に取付く。折曲延長２６間の桟瓦葺，切妻屋根，真壁造の簡素な土塀で，石の土台に建ち，外側に２間毎に鉄棒で控えをとり，西北部に裏口を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001816"},{"id":"00001814","register_sub_id":"101","register_pk":"102804","name":"児玉家住宅蚕室","kana":"こだまけじゅうたくさんしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.379498,"lng":138.332703,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0079","desc":"主屋の背後北東方に位置する東西棟，桟瓦葺，越屋根付切妻造の総２階建蚕室。 桁行９間，梁行４間の規模で，１階は土間，２階は３間×４間の蚕室３室とし，南面２階に刎ねだしのベランダを付ける。養蚕最盛期の養蚕農家の屋敷構えを伝えるものとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001814"},{"id":"00001812","register_sub_id":"101","register_pk":"102802","name":"児玉家住宅主屋","kana":"こだまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.37931407,"lng":138.33261669,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積406㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0077","desc":"千曲川を望む南西斜面の山裾に位置し，松代禰津往還道に南面して屋敷地を構える。主屋は，平面間口１５間半，梁行６間の桟瓦葺，越屋根付切妻造，総２階建，平入の蚕室型民家で，南面を下屋形式と出梁によるベランダ状形式とに分けている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001812"},{"id":"00001813","register_sub_id":"101","register_pk":"102803","name":"児玉家住宅土蔵","kana":"こだまけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.37912707,"lng":138.33277352,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0078","desc":"敷地の東南端に位置し，亀甲積の石垣擁壁の上に建つ。桁行６間，梁行３間の２階建土蔵で，屋根は東西棟，桟瓦葺，切妻造の置屋根とし，北面に下屋を設けて蔵前とする。外壁の腰に平石を石積風に張り，海鼠壁仕上げとしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001813"},{"id":"00001815","register_sub_id":"101","register_pk":"102805","name":"児玉家住宅長屋","kana":"こだまけじゅうたくながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.37930931,"lng":138.33283755,"geo_status":"db","era":"明治34頃","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0081","desc":"主屋の東方，敷地の東辺に沿って建つ。桁行１１間，梁行３間の南北棟，桟瓦葺，切妻造建屋で，南に乾燥部屋，北妻面には東門が取付く。内部は表長屋，長屋，便所に分けられ，西前面を土庇とし，東面の開口には窓庇をつけて景観に配慮したつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001815"},{"id":"00001818","register_sub_id":"101","register_pk":"102808","name":"児玉家住宅西塀","kana":"こだまけじゅうたくにしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.37927992,"lng":138.33230099,"geo_status":"db","era":"明治34頃","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"土造、延長16m","structure_material":"土造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0087","desc":"敷地の西辺を限る塀で，石塁の上に築かれる。長１０間，南北棟，桟瓦葺，切妻屋根の真壁造土塀で，石塁の天端から上の腰部を土壁で袴状に塗籠めている点に特徴がある。南端は妻面を往還道にみせて，西門，南塀石垣とともに枡形をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001818"},{"id":"00001822","register_sub_id":"101","register_pk":"102812","name":"児玉家住宅西門","kana":"こだまけじゅうたくにしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.37914934,"lng":138.33232662,"geo_status":"db","era":"明治34頃","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0085","desc":"屋敷地の西南端に西向きに開けられた門で，南北棟，桟瓦葺，切妻造の２間薬医門とし，右脇間に表門同様の潜戸を設ける。往還道沿いの石垣と塀，石塁上に築かれた西辺の土塀により枡形風の門構えをとる点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001822"},{"id":"00001821","register_sub_id":"101","register_pk":"102811","name":"児玉家住宅東門","kana":"こだまけじゅうたくひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.37941466,"lng":138.33283928,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、瓦葺、間口2.4m、9.8m袖塀付","structure_material":"木造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0084","desc":"主屋と蚕室に囲われた裏庭に通じる間口１間の棟門で，南北棟，桟瓦葺，切妻造とし，南は長屋の北妻面西端に取り付き，北は屋根付土塀に接続する。長屋の東面および馬屋東南端から南に降りる土塀からは引っ込んだ門構えをとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001821"},{"id":"00001817","register_sub_id":"101","register_pk":"102807","name":"児玉家住宅味噌部屋・乾燥室","kana":"こだまけじゅうたくみそべや・かんそうしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.37918345,"lng":138.33283279,"geo_status":"db","era":"明治34頃","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0082","desc":"土蔵と長屋の間に建てられた南北棟，桟瓦葺，切妻造建屋で，桁行２間梁行２間の味噌部屋と桁行４間梁行２間の乾燥部屋から成る。東面は長屋と面一とした白壁で，西屋根面を土蔵北面の下屋庇に矩折れに繋げるなど内外ともみえがかりに配慮したつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001817"},{"id":"00001823","register_sub_id":"101","register_pk":"102813","name":"児玉家住宅南塀石垣","kana":"こだまけじゅうたくみなみべいいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県東御市大字和7785","lat":36.37910789,"lng":138.33246672,"geo_status":"db","era":"明治34頃","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"石造、延長34m","structure_material":"石造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0086","desc":"表門西端から松代禰津往還道に沿って西門に至る約４０ｍの石積擁壁で，傾斜地斜面の造成に伴い築造された見かけ３段の亀甲積石垣に木造塀の土台石を載せる。土蔵の下の亀甲積石垣，表門，西門とともに往還道沿いに小城郭風の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001823"},{"id":"00001256","register_sub_id":"101","register_pk":"102246","name":"小林家住宅北蔵（味噌蔵・文庫蔵）","kana":"こばやしけじゅうたくきたぐら（みそぐら・ぶんこぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市稲里町田牧784-1","lat":36.593849,"lng":138.173676,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造２階建，瓦葺，建築面積67㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"20 － 0020","desc":"主屋の背後に位置し、蔵前を共有して東に南北棟、瓦葺切妻屋根の文庫蔵を、西に東西棟、瓦葺切妻屋根の味噌蔵を建てる。文庫蔵は桁行２間半梁間２間、味噌蔵は桁行５間梁間２間半の規模で、棟の向きに加えて、味噌蔵を置屋根形式として変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001256"},{"id":"00001258","register_sub_id":"101","register_pk":"102248","name":"小林家住宅薫蒸蔵","kana":"こばやしけじゅうたくこうじょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市稲里町田牧784-1","lat":36.59349576,"lng":138.17377962,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建，鉄板葺，建築面積12㎡","structure_material":"土蔵造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"20 － 0022","desc":"正門の東側に接して建ち、正門西側の土塀とともに門構えを構成する鉄板葺、寄棟屋根の小規模土蔵。南面は土塀と同様の亀甲石積の上に建ち、腰を板貼りとする閉鎖的な土蔵であるが、軒回りは水平線を強調した洋風の造りとする点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001258"},{"id":"00001255","register_sub_id":"101","register_pk":"102245","name":"小林家住宅主屋","kana":"こばやしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市稲里町田牧784-1","lat":36.59372379,"lng":138.17377335,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造２階建，瓦葺，建築面積409㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"20 － 0019","desc":"犀川沿い川中島地方の穀倉地として栄えた地区のもと庄屋の邸宅。瓦葺入母屋造の２階建大規模農家で、南面正面に入母屋造の式台玄関を付けた重厚な構えをとる。内部は、西側を土間、東側を６間とし、各部屋それぞれ意匠を凝らした造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001255"},{"id":"00001257","register_sub_id":"101","register_pk":"102247","name":"小林家住宅正門","kana":"こばやしけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市稲里町田牧784-1","lat":36.59349172,"lng":138.17373059,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造薬医門，瓦葺，建築面積4.5㎡","structure_material":"木造薬医門","registered":"1999.08.23(平成11.08.23)","register_no":"20 － 0021","desc":"主屋式台玄関の南方、やや西寄りに開かれた瓦葺、薬医門形式の表門で、東側に燻蒸蔵を配置する。道路からは２０ｍほど退いた位置に建てられ、門前には３列の石畳を敷いて庄屋屋敷に相応しい奥行感のあるアプローチ空間をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001257"},{"id":"00008275","register_sub_id":"101","register_pk":null,"name":"五明家住宅離れ座敷","kana":"ごみょうけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"長野県","address":null,"lat":null,"lng":null,"geo_status":"missing","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0358","desc":"敷地の中央に位置する。寄棟造桟瓦葺で、四周に下屋をまわす。東西に二室並べ、南面に畳縁、他三面に榑縁をまわす。西側の主座敷にはトコやトコ脇、付書院を構え、中央を繰形で六角形に象る棹縁天井を高く張る。繊細で、凝ったつくりになる書院座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008275"},{"id":"00008276","register_sub_id":"101","register_pk":null,"name":"五明家住宅文庫蔵","kana":"ごみょうけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":null,"lat":null,"lng":null,"geo_status":"missing","era":"明治前期／昭和12年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0359","desc":"離れ座敷の北面に接する南北棟の切妻造桟瓦葺。桁行３．６ｍ梁間３．６ｍ、切石積基礎上に建つ２階建土蔵。外壁は漆喰仕上げで、東面に出入口を開け、庇を掛ける。庇の軒桁に雲紋の持送りを用いるなど、丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008276"},{"id":"00016663","register_sub_id":"101","register_pk":"579147","name":"小山家住宅主屋","kana":"こやまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和後","pref":"長野県","address":"長野県長野市青木島町大塚字久新川原983","lat":36.610739,"lng":138.189554,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0687","desc":"犀川右岸に位置する旧家の主屋。敷地中央に南面して建つ寄棟造桟瓦葺。正面は屋根を切上げ下屋を通し、棟に越屋根を上げる。右土間で床上は前後二列に三室を並べ、正背面に縁を通す。上手列の二室は座敷で西面に床を設ける。当地の伝統的な間取を伝える民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016663"},{"id":"00016664","register_sub_id":"101","register_pk":"579148","name":"小山家住宅土蔵及び離れ","kana":"こやまけじゅうたくどぞうおよびはなれ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市青木島町大塚字久新川原983","lat":36.610864,"lng":138.189484,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0688","desc":"主屋北西に接続する。東西棟の土蔵は二階建、置屋根形式の切妻造桟瓦葺で窓廻りや軒蛇腹を漆喰で丁寧に仕上げる。離れは桁行三間半、梁間二間半の南・東面に下屋の廊下を廻らす。主室に一間半幅の床を設け、落掛は丸太。旧家の屋敷構を構成する土蔵及び離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016664"},{"id":"00016665","register_sub_id":"101","register_pk":"579149","name":"小山家住宅長屋門","kana":"こやまけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市青木島町大塚字久新川原983","lat":36.610636,"lng":138.189683,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0689","desc":"敷地東辺に位置する桁行七間梁間二間半、切妻造桟瓦葺で背面に下屋を通す。外壁は大壁で軒先まで塗込める。中央南寄りの門口は冠木に男梁女梁を重ねるなど重厚なつくり。南北を室として南室は床板張の米蔵、北室は土間の納屋とする。風格ある構えの長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016665"},{"id":"00003092","register_sub_id":"101","register_pk":"104082","name":"坂井銘醸主屋","kana":"さかいめいじょうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.490997,"lng":138.150482,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、茅葺、建築面積437㎡","structure_material":"木造平屋一部2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0112","desc":"北国街道沿いに東面して建つ間口１５間半梁行６間半規模の大型茅葺民家で，宝暦１０年の大火後の復興とされる。南方下手を土間とし，西方背面中央部に座敷棟を角屋状に突出させる。北方上手の間口２間の式台に名主家としての権威と格式が示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003092"},{"id":"00003093","register_sub_id":"101","register_pk":"104083","name":"坂井銘醸文庫蔵","kana":"さかいめいじょうぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.49107,"lng":138.150146,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0113","desc":"主屋の北西方，北国街道に直交する県道戸倉停車場線（駅前通り）に北面を向けて建つ。東西棟，切妻造，桟瓦葺の平入，２階建土蔵で，桁行５間梁間２間半規模とし，南面中央に下屋を差掛けて蔵前をつくる。軒や垂木を塗込めた丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003093"},{"id":"00013788","register_sub_id":"101","register_pk":"507750","name":"佐藤家住宅（三ツ引）主屋及び奥上段","kana":"さとうけじゅうたく（みつびき）おもやおよびおくじょうだん","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上田市上塩尻字南側90","lat":36.41824167,"lng":138.21575,"geo_status":"db","era":"江戸後期／江戸末期改修、昭和前期増築改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、茅葺（鉄板仮葺）、建築面積288㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"20 － 0571","desc":"上田市市街地北西に位置し、敷地北側に南面する。主体部西半は平屋建寄棟造茅葺（鉄板仮葺）、東半は二階建切妻造桟瓦葺で棟に越屋根を二つ設ける。西半は床上部で三列六室とする。北西に平屋建寄棟造茅葺（鉄板仮葺）の奥上段（座敷棟）を付す大規模民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013788"},{"id":"00013793","register_sub_id":"101","register_pk":"507755","name":"佐藤家住宅（三ツ引）穀蔵","kana":"さとうけじゅうたく（みつびき）こくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側90","lat":36.418175,"lng":138.21560278,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"20 － 0576","desc":"主屋の南に東面する桁行三間、梁間二間半、土蔵造二階建、切妻造桟瓦葺の東西棟。東妻を戸口として庇を付し、二階に窓を一箇所開ける。外壁は軒裏まで塗込め中塗仕上とする。一、二階内部は一室の板敷とする。小規模ながら敷地中央の景観を特徴づける穀蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013793"},{"id":"00013789","register_sub_id":"101","register_pk":"507751","name":"佐藤家住宅（三ツ引）蚕室","kana":"さとうけじゅうたく（みつびき）さんしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側90他","lat":36.41802222,"lng":138.21567778,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積118㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"20 － 0572","desc":"敷地南端に建つ二階建切妻造桟瓦葺の東西棟で、棟全体に越屋根を設ける。一階北に二箇所の戸口を設け、外壁は軒裏まで塗込めて中塗で仕上げ、両妻は漆喰塗で仕上げる。内部一階は二室の土間、二階は三室の板敷で、各室の南北両面に窓を開けて蚕室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013789"},{"id":"00013791","register_sub_id":"101","register_pk":"507753","name":"佐藤家住宅（三ツ引）消毒室","kana":"さとうけじゅうたく（みつびき）しょうどくしつ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側90","lat":36.41811389,"lng":138.21564722,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"20 － 0574","desc":"主屋の南に建つ土蔵造二階建、切妻造平入桟瓦葺の南北棟で、棟中央に越屋根を設ける。外壁は軒裏まで塗込め中塗仕上とする。内部一階は一室で、壁と天井を土で塗込め密封し漆喰塗仕上とした消毒室、二階は一室の板敷で蚕室とする。蚕種業の様相を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013791"},{"id":"00013792","register_sub_id":"101","register_pk":"507754","name":"佐藤家住宅（三ツ引）文庫蔵","kana":"さとうけじゅうたく（みつびき）ぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側90","lat":36.41831667,"lng":138.21551667,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"20 － 0575","desc":"主屋の西に建つ土蔵造二階建、切妻造桟瓦葺の南北棟。北妻を戸口とし、銅板葺下屋を付し蔵前とする。外壁は軒裏まで塗込めて中塗で仕上げ、南と東に窓を開ける。内部一階は一室の板敷、二階は一室の畳敷とする。棟に家紋入の大振りの鬼瓦を載せた文庫蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013792"},{"id":"00013794","register_sub_id":"101","register_pk":"507756","name":"佐藤家住宅（三ツ引）味噌蔵","kana":"さとうけじゅうたく（みつびき）みそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市上塩尻字南側90","lat":36.41825556,"lng":138.21546944,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"20 － 0577","desc":"主屋の西に建つ土蔵造二階建、切妻造桟瓦葺の東西棟。東と北に戸口を設け、北妻は庇を付し二階に窓を一箇所開ける。外壁は軒裏まで塗込め中塗仕上とし、庇の軒裏も塗込める。内部一階は二室の土間で、二階は一室の板敷。主屋西側の景観を形成する味噌蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013794"},{"id":"00013790","register_sub_id":"101","register_pk":"507752","name":"佐藤家住宅（三ツ引）物置","kana":"さとうけじゅうたく（みつびき）ものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県上田市上塩尻字南側90","lat":36.41811667,"lng":138.215775,"geo_status":"db","era":"江戸末期／明治後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"20 － 0573","desc":"主屋南東に建つ二階建切妻造桟瓦葺の南北棟で、棟中央に越屋根を設ける。東西面に戸口を設け、外壁は軒裏まで塗込めて中塗で仕上げ、出桁で持出した二階西面は漆喰で仕上げる。内部一階は一室の土間で、二階は二室の板敷の蚕室が残る。敷地東辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013790"},{"id":"00013796","register_sub_id":"101","register_pk":"507758","name":"佐藤家住宅（三ツ引）門","kana":"さとうけじゅうたく（みつびき）もん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上田市上塩尻字南側90","lat":36.418075,"lng":138.21576389,"geo_status":"db","era":"江戸末期／明治中期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.6m、左右袖塀付","structure_material":"木造","registered":"2021.06.24(令和3.06.24)","register_no":"20 － 0579","desc":"敷地東辺に建つ表門。切妻造桟瓦葺で、角柱の本柱と控柱間に貫を通し、本柱間に冠木を渡して軸部を固め、軒桁を腕木で支持する。本柱間に両開きの板扉を吊り、控柱上部に小屋根を載せる。両脇は半間の塀で北に潜戸を付す。旧家の屋敷地の表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013796"},{"id":"00013795","register_sub_id":"101","register_pk":"507757","name":"佐藤家住宅（三ツ引）屋敷神","kana":"さとうけじゅうたく（みつびき）やしきがみ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県上田市上塩尻字南側90","lat":36.41838333,"lng":138.21550278,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"20 － 0578","desc":"主屋西方の石垣上に南面する方一間の稲荷社で、起りのある切妻造妻入鉄板葺。切石積基壇上の土台に角柱を立て、上部は頭貫で固めて台輪を置き、組物は出三斗とする。内部は格子戸で前後に区画し、後室に宮殿を配する。敷地北西角の景観を形成する屋敷神。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013795"},{"id":"00009004","register_sub_id":"101","register_pk":"162364","name":"佐藤家住宅奥土蔵","kana":"さとうけじゅうたくおくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県佐久市協和字上三井225-1","lat":36.26140004,"lng":138.34583659,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積31㎡、味噌部屋付","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0401","desc":"主屋の西に位置する。桁行６．６ｍ梁間３．７ｍの二階建土蔵で、外壁は腰下見板張とする漆喰仕上げとし、内部は板床とする。付設する味噌部屋は木造平屋建で、招屋根とし桟瓦を葺く。腰下見板張で、漆喰仕上げの真壁とする。屋敷の一構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009004"},{"id":"00009001","register_sub_id":"101","register_pk":"162361","name":"佐藤家住宅勘定部屋","kana":"さとうけじゅうたくかんじょうべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県佐久市協和字上三井225-1","lat":36.26121129,"lng":138.34605922,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0398","desc":"通り沿いの石垣上、伴部屋と東土蔵の間に建つ。両下造桟瓦葺。通り側は腰下見板張で、その上に横格子窓を穿ち、上部を漆喰仕上げの真壁とする。主屋側は北寄りに袖壁を設けるだけで開放的に扱う。内部は土間床で小屋組を現し、南面に米櫃を造り付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009001"},{"id":"00009000","register_sub_id":"101","register_pk":"162360","name":"佐藤家住宅伴部屋","kana":"さとうけじゅうたくともべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県佐久市協和字上三井225-1","lat":36.26125969,"lng":138.34609309,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積21㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0397","desc":"通り沿いの石垣に建つ木造二階建。桁行４．５ｍ梁間４．６ｍ、切妻造桟瓦葺。内部は一・二階とも一室。北側面は腰下見板張、漆喰仕上げの真壁造とする。通り側は開放的に扱い、一階は出格子、二階は出窓として持ち出す。軽快な正面構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009000"},{"id":"00009002","register_sub_id":"101","register_pk":"162362","name":"佐藤家住宅東土蔵","kana":"さとうけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県佐久市協和字上三井225-1","lat":36.26116531,"lng":138.34602292,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0399","desc":"通り沿いの石垣上に建つ二階建土蔵。桁行７．３ｍ梁間５．５ｍ、切妻造桟瓦葺の置屋根。外壁は腰下見板張で、漆喰仕上げ。北妻に出入口を穿つ。一階西南隅一間一間半を欠き取り、井戸屋を設ける。伴部屋からの連続する三棟が重厚な構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009002"},{"id":"00006244","register_sub_id":"101","register_pk":"107228","name":"三五荘（中央工学校軽井沢山荘）","kana":"さんごそう（ちゅうおうこうがっこうかるいざわさんそう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢1052-73","lat":36.33425692,"lng":138.61975668,"geo_status":"db","era":"江戸末期／昭和9移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、茅葺、建築面積252㎡、地下室付","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"20 － 0314","desc":"桁行１１間，梁行７間規模，茅葺の大型民家で，妻面に整然とした化粧貫を重ね，屋根中央部を高く突き出す甲州盆地東部の上層農家建築の特徴をもつ。移築に際し，鉄筋コンクリート造の半地下室を設け，土間を板敷とする。民家建築の初期の移築例としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006244"},{"id":"00010288","register_sub_id":"101","register_pk":"199061","name":"塩川家住宅主屋","kana":"しおかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県小諸市大字森山字宮前700","lat":36.297917,"lng":138.43589,"geo_status":"db","era":"明治27年／平成18年改修","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積291㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0465","desc":"敷地の北辺西寄りに建つ木造二階建。二尺超の成の差物などにマツの長大材を使い、力感ある軸部構成をもつ。庭を望む座敷では、トコの両脇に天袋付のトコ脇を設ける独特の構えとし、室境に菱万字文の手の込んだ組子欄間を飾るなど、豪壮で気品を備えた近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010288"},{"id":"00003977","register_sub_id":"101","register_pk":"104967","name":"塩原家住宅米蔵","kana":"しおはらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市今井上耕地5990","lat":36.15037442,"lng":137.89049449,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積51㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"20 － 0177","desc":"主屋正面の右手前に建ち，主屋側に正面を向ける土蔵。切妻造，桟瓦葺，置屋根形式で，正面側に下屋を設ける。下屋柱も含めて腰部は海鼠壁とし，上部は漆喰塗とする。主として米穀を収めるのに使われていたと伝えられ，丁寧なつくりの土蔵になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003977"},{"id":"00003975","register_sub_id":"101","register_pk":"104965","name":"塩原家住宅主屋","kana":"しおはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市今井上耕地5990","lat":36.150433,"lng":137.890274,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積464㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"20 － 0175","desc":"敷地中程に建つ。入母屋造，桟瓦葺で，棟上にはほぼ全長に渡って越屋根を上げる。正面中程に土間玄関を開き，その左には式台玄関を設けている。背面側には離れを突出させ，北東隅には土蔵を建て包む。二階は主として養蚕室として使用されていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003975"},{"id":"00003976","register_sub_id":"101","register_pk":"104966","name":"塩原家住宅門","kana":"しおはらけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市今井上耕地5990","lat":36.1501137,"lng":137.89047193,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、間口1.8m","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"20 － 0176","desc":"敷地東寄りに建つ。屋根は袖塀部分とも桟瓦葺で，棟は輪違い積みとする。袖塀は腰部を板張とし，上部は漆喰塗。全体に簡素ではあるが，間口も広く，豪壮な主屋に見合った格を備える表門であり，敷地景観を構成する上で欠かすことのできない建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003976"},{"id":"00006219","register_sub_id":"101","register_pk":"107203","name":"塩屋醸造小文庫蔵","kana":"しおやじょうぞうこぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.65588,"lng":138.315887,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0311","desc":"主屋の東方に位置し，西面して建つ。桁行３間，梁間２間半，土蔵造２階建，切妻造，桟瓦葺。小屋組は和小屋。外観は中塗仕上げで，出入口枠を丁寧に形づくり，前面に庇を設け，繰形を施した持送りを付ける。全体として簡素なつくりでまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006219"},{"id":"00006227","register_sub_id":"101","register_pk":"107211","name":"塩屋醸造離れ","kana":"しおやじょうぞうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.65581763,"lng":138.3159245,"geo_status":"db","era":"明治後期／平成15改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0303","desc":"主屋の南東方に位置する。桁行５間，梁間２間半規模，木造平屋建，切妻造，桟瓦葺とし，主屋と廊下で繋ぐ。内部は南方の庭に沿って廊下を通し，床の間を設けた６畳の座敷と８畳の次の間を並べる。外観は中塗仕上げとし，敷地居住部分の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006227"},{"id":"00013396","register_sub_id":"101","register_pk":"368481","name":"島木赤彦寓居","kana":"しまきあかひこぐうきょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県塩尻市大字広丘原新田289-3","lat":36.15286111,"lng":137.94519722,"geo_status":"db","era":"明治前期／明治後期増築、昭和30年代改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、金属板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"20 － 0565","desc":"塩尻市北部の広丘原新田にあり、善光寺街道に面して敷地を占める。木造平屋建、切妻造金属板葺で、もと太田家住宅主屋の角屋。緩勾配の切妻屋根に雀踊を飾り、本棟造風の外観を持つ。内部は八畳一室で北に玄関、南に縁側を付す。街道沿いの様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013396"},{"id":"00010143","register_sub_id":"101","register_pk":"197976","name":"下伊那教育会旧黒須家土蔵","kana":"しもいなきょういくかいきゅうくろすけどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県飯田市仲ノ町358-3","lat":35.51595,"lng":137.830047,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0453","desc":"会館から通りを挟んだ南側敷地に建つ。土蔵造二階建で置屋根式の桟瓦葺とし、西妻面に下屋を設け、南面全長に吹放しの下屋を通す。外壁は腰下を海鼠壁とし、鉢巻を廻らす。柱にクリの古材などを再利用しつつ、明治後期に再建されたと考えられる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010143"},{"id":"00010144","register_sub_id":"101","register_pk":"197977","name":"下伊那教育会旧黒須家門","kana":"しもいなきょういくかいきゅうくろすけもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県飯田市仲ノ町358-3","lat":35.51601677,"lng":137.82996758,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0454","desc":"土蔵の西方に建つ、もと黒須家の表門。間口二・四メートルの薬医門で、切妻造桟瓦葺とする。本柱間の板扉を藁座で吊り、化粧屋根裏では割竹の小舞下地を現しとするなど特徴的な仕様になる。かつての武家地の景観を彷彿とさせ、飯田藩政期の貴重な遺例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010144"},{"id":"00016668","register_sub_id":"101","register_pk":"579152","name":"水明楼","kana":"すいめいろう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県小諸市丁字中棚町455-1","lat":36.322715,"lng":138.417649,"geo_status":"db","era":"明治33年","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、茅葺、建築面積41㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0692","desc":"小諸城跡南側の西斜面に位置する小諸義塾塾長の木村熊二の旧書斎。二階建寄棟造茅葺で、二階の南・西面を廻る濡縁に庇を付し、東面に下屋を付す。二階南半は座敷とし、床を構え、書院に大きく下地窓を開ける。島崎藤村などが訪れた眺望優れた楼閣風の建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016668"},{"id":"00002036","register_sub_id":"101","register_pk":"103026","name":"巣山家住宅東土蔵","kana":"すやまけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県塩尻市大字木曽平沢字西町1561-1","lat":35.97940317,"lng":137.83017238,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"20 － 0090","desc":"敷地中央，主屋の奥に庭を挟んで建つ。シモノクラと呼ばれ，什器等を収蔵した。棟木に昭和７年上棟の墨書がある。切妻造・２階建で，西土蔵と通路を挟んで建ち，一連の鉄板葺屋根を架ける。外壁は腰部を海鼠壁，上部を白漆喰塗とした丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002036"},{"id":"00008994","register_sub_id":"101","register_pk":"162354","name":"諏訪湖ホテル菊の間","kana":"すわこほてるきくのま","category":"住宅","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪市湖岸通り4-670-4","lat":36.04743394,"lng":138.11308825,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0391","desc":"迎賓館の東南に並び建つ、建築面積１９０㎡、木造平屋建、入母屋造桟瓦葺の和風建築。内外とも良材を用い、座敷は数寄屋造で統一しており、全体に装飾を控え洗練された意匠になる。洋風建築の迎賓館と対をなして、近代別邸建築の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008994"},{"id":"00008993","register_sub_id":"101","register_pk":"162353","name":"諏訪湖ホテル迎賓館","kana":"すわこほてるげいひんかん","category":"住宅","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪市湖岸通り4-670-4","lat":36.04759574,"lng":138.11300259,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積216㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0390","desc":"片倉館の南隣の敷地北辺に建つ。建築面積２１６㎡、木造二階建、寄棟造桟瓦葺で、外観はスパニッシュ風の意匠でまとめる。内部は、一階を洋室、二階を和室としイタリア産大理石や台湾檜など良材を用いる。昭和初期の別邸建築における洋館の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008993"},{"id":"00011693","register_sub_id":"101","register_pk":"210709","name":"瀧澤家住宅主屋","kana":"たきざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字磯部字石原122","lat":36.482857,"lng":138.159596,"geo_status":"db","era":"江戸中期／江戸後期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋一部2階建、茅葺、建築面積333㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"20-0511","desc":"敷地の中央に西面する。桁行一二間、梁間六間半、寄棟造茅葺。南半は土間と旧馬屋であり、土間と床上部境は一間毎に柱を立て、大黒柱もなく古式を示す。居間の間口に一尺の伸びがある点など、近世における当地域の特徴をよく留める大型民家として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011693"},{"id":"00011694","register_sub_id":"101","register_pk":"210710","name":"瀧澤家住宅土蔵","kana":"たきざわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字磯部字石原122","lat":36.483015,"lng":138.159644,"geo_status":"db","era":"江戸後期／平成5年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、鉄板葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"20-0512","desc":"主屋の北に南面する。桁行九・一メートル、梁間四・六メートルの二階建、切妻造、置屋根形式で南面に下屋庇を設ける。南面に二所の扉口を開き、二階西面に一所の窓を設け、いずれも鳥居枠で飾る。主屋と一体となり農家の屋敷構えを良好に形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011694"},{"id":"00011695","register_sub_id":"101","register_pk":"210711","name":"瀧澤家住宅長屋門","kana":"たきざわけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字磯部字石原122","lat":36.482843,"lng":138.159388,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、茅葺、建築面積95㎡","structure_material":"土蔵造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"20-0513","desc":"敷地の西面を画す長屋門。屋根は茅葺で、南を寄棟造、北を切妻造と違える。中央やや南寄りに門口を開き、南に桁行三間の板敷、北に桁行六間の土間の物置とする。門口では、桟梁より上を塗込め、丁寧な造り。主屋と共に茅葺の外観が歴史的景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011695"},{"id":"00001784","register_sub_id":"101","register_pk":"102774","name":"武重本家酒造及び武重家住宅奥座敷","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27355186,"lng":138.33904942,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0048","desc":"主屋の西方に接続するが，建替以前の主屋の座敷であり，中山道沿いに建つ店（ミセ）西端の門に向きあう。北に６畳間を連ねた１０畳間２列の構成で，南に縁を回し，主屋との接続部に８畳間と４畳間を矩折りに配置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001784"},{"id":"00001783","register_sub_id":"101","register_pk":"102773","name":"武重本家酒造及び武重家住宅主屋","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27355596,"lng":138.33919594,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積236㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0047","desc":"中山道望月宿と芦田宿との間の宿にあたる茂田井に位置し，旧中山道に沿った敷地の北奥に醸造施設を配置する。主屋は，総２階建，越屋根付きの切妻造で，両妻面を塗籠て土蔵風に造る。西に奥座敷を接続させ，１階東端を醸造蔵へ抜ける通庭とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001783"},{"id":"00001843","register_sub_id":"101","register_pk":"102833","name":"武重本家酒造及び武重家住宅水槽","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくすいそう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.2736484,"lng":138.33870794,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ2.5m、幅3m、奥行2m","structure_material":"煉瓦造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0061","desc":"離れの敷地の最奥，離れの北側裏庭に位置する。３ｍ×２ｍの平面規模，高さ煉瓦３８段のイギリス積煉瓦造水槽で，内部を家庭用と醸造用との２槽に分ける。石積擁壁下の井戸に対応した貯水槽で，造り酒屋の近代化を物語る設備として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001843"},{"id":"00001794","register_sub_id":"101","register_pk":"102784","name":"武重本家酒造及び武重家住宅茶室","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27351068,"lng":138.33864046,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0060","desc":"隠居所としての離れの敷地西南隅寄りに建つ。内部は４畳半の１室構成で，西壁を塀と一体的に造る。外観は，東西棟の桟瓦葺，入母屋造で，小規模ながら重厚な降り棟をもち，妻や軒裏を塗籠とするなど隅櫓的の雰囲気を漂わす造型意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001794"},{"id":"00001798","register_sub_id":"101","register_pk":"102788","name":"武重本家酒造及び武重家住宅中門","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27348924,"lng":138.3392617,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、間口2.0m","structure_material":"木造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0055","desc":"門長屋北面の突出部と主屋南面との間に位置し，門長屋・東蔵・主屋玄関部・醸造場への通り庭に囲われたアプローチ区域とプライベートな主屋南庭とを区切る。間口２ｍ程の切妻造，桟瓦葺の門で，欅材を用いた丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001798"},{"id":"00001787","register_sub_id":"101","register_pk":"102777","name":"武重本家酒造及び武重家住宅西蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27350441,"lng":138.33880608,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積158㎡","structure_material":"土蔵造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0054","desc":"店の西方，一段高い敷地に建つ桁行１１間，梁行４間規模の，東西棟，桟瓦葺，切妻造の平家建土蔵で，東寄りを３戸前の庫室とし，西寄り中央に裏庭に通じる出入口を設ける。東蔵，門長屋，店とともに旧中山道の街道景観を造る一要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001787"},{"id":"00001785","register_sub_id":"101","register_pk":"102775","name":"武重本家酒造及び武重家住宅離れ","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27360997,"lng":138.33871277,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0059","desc":"屋敷地南西端隅部に石積擁壁を築いて整地した南北に長い敷地の奥寄りに建つ。桁行５間半，梁行４間半規模の南北棟，桟瓦葺，切妻造で，主屋からは西蔵経由の登廊でつながれ，南側に８畳間と６畳間を配置し，西塀に沿って便所と浴室を延ばす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001785"},{"id":"00001810","register_sub_id":"101","register_pk":"102800","name":"武重本家酒造及び武重家住宅離れ石垣塀","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくはなれいしがきべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27349628,"lng":138.33870152,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造及び木造、延長10m","structure_material":"石造及び木造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0062","desc":"離れの敷地の北，東，南の三辺に石を積んで擁壁を造り，その上に桟瓦葺，両流の小屋根を架けた真壁造の塀を廻す。擁壁は，亀甲積あるいは矢筈積の丁寧な造りで，程良い弛みをつけるなど，塀と相まって小城郭的な景観を旧中山道沿いにつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001810"},{"id":"00001786","register_sub_id":"101","register_pk":"102776","name":"武重本家酒造及び武重家住宅東蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27340138,"lng":138.33935767,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0051","desc":"屋敷地の旧中山道沿い南辺から東辺に回る水路の石積擁壁の上に建つ。もと米蔵で，桁行５間，梁行２間の南北棟，桟瓦葺，置屋根型式の２階建土蔵。西方に連なる門長屋，店，西蔵とともに旧中山道沿いの街道景観をつくる主要な構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001786"},{"id":"00001809","register_sub_id":"101","register_pk":"102799","name":"武重本家酒造及び武重家住宅東塀","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくひがしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.2734886,"lng":138.33935772,"geo_status":"db","era":"明治42頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、瓦葺、延長30m","structure_material":"木造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0058","desc":"主屋の北東端から発し，敷地東辺を流れる水路に沿って醸造蔵の方に延びる長９間の木造塀で，４間分のところで緩く折れ曲がる。桟瓦葺の小屋根を載せた真壁造の塀で，土壁を白漆喰で仕上げて東蔵から続く屋敷東面の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001809"},{"id":"00001789","register_sub_id":"101","register_pk":"102779","name":"武重本家酒造及び武重家住宅文庫蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27367386,"lng":138.33910494,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0049","desc":"奥座敷の北方に庭園をはさんで建つ。主屋の北西端から連絡する東西棟，桟瓦葺の置屋根形式の２階建土蔵で，東妻面に蔵前を付す。桁行４間，梁行２間半の規模で，開口部回りは黒漆喰仕上げとし，軒の鉢巻部には刳型を付けた丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001789"},{"id":"00001793","register_sub_id":"101","register_pk":"102783","name":"武重本家酒造及び武重家住宅店","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくみせ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27346079,"lng":138.33903659,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積87㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0053","desc":"門長屋の西に水路に沿って延びる桁行１２間の細長い建屋で，中央部を２階建の塗屋とし，西寄り５間分を門長屋として中央に門を開ける。街道沿いの南面は腰を押縁下見とし，東寄りは出格子の瓦葺の小庇を付けるなど街道沿いの景観に変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001793"},{"id":"00001790","register_sub_id":"101","register_pk":"102780","name":"武重本家酒造及び武重家住宅味噌蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27364368,"lng":138.33920235,"geo_status":"db","era":"明治45頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0050","desc":"主屋の北方，文庫蔵の東方に位置する。桁行３間，梁行２間の東西棟，桟瓦葺，置屋根型式の２階建土蔵で，文庫蔵と同型式の造りになり，文庫蔵の蔵前と西妻面との間に裏門を設ける。文庫蔵とともに屋敷地と醸造用地との境界をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001790"},{"id":"00001788","register_sub_id":"101","register_pk":"102778","name":"武重本家酒造及び武重家住宅南蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字東町2181-1","lat":36.27319134,"lng":138.33908656,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積127㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0074","desc":"門長屋斜向かいの角地に建つ。旧中山道に妻面を見せた桁行７間，梁行３間半の南北棟，桟瓦葺，切妻造，置屋根形式の土蔵に矩折りに切妻造，下屋付きの土蔵をつなげる。東蔵・門長屋・店に向きあうことで旧中山道間の宿の伝統的町並み景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001788"},{"id":"00001792","register_sub_id":"101","register_pk":"102782","name":"武重本家酒造及び武重家住宅門長屋","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27344107,"lng":138.33920552,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0052","desc":"東蔵の西に接続する長屋門風の建屋で，西に店が連なる。桁行５間半，梁行２間規模の東西棟，桟瓦葺，切妻造，平入で，東蔵寄りの２間半を門に充てる。旧中山道に沿った南面は，腰を押縁下見，小壁を真壁造とし，間に連子窓を入れて表構えを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001792"},{"id":"00001796","register_sub_id":"101","register_pk":"102786","name":"武重本家酒造及び武重家住宅屋敷神","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくやしきがみ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27368741,"lng":138.33897112,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積8.6㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0056","desc":"西蔵の北方奥，文庫蔵の北西方に位置する。八尺四方の入母屋造，銅板葺，外部腰縦板張り，上部に連子を入れた覆屋に，鎌倉八幡宮から分祠された一間社流造の八幡社を納め，前面に切妻造，銅板葺の拝殿を付ける。現当主が誕生した際の造替と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001796"},{"id":"00001797","register_sub_id":"101","register_pk":"102787","name":"武重本家酒造及び武重家住宅屋敷神鳥居","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくやしきがみとりい","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27365417,"lng":138.33899715,"geo_status":"db","era":"文政10","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"石造、高さ2.3m、間口2.8m","structure_material":"石造","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0057","desc":"間口２ｍ７５，高さ２ｍ２５の石造鳥居。明神鳥居の柱上端に台輪をいれた稲荷鳥居の形式をもつが，笠木には反りをあまり大きくつけておらず，二段亀腹の礎石の形状も特異である。屋敷神とともに造り酒屋の屋敷構えを構成する一要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001797"},{"id":"00003563","register_sub_id":"101","register_pk":"104553","name":"田中本家博物館内塀及び門","kana":"たなかほんけはくぶつかんうちべいおよびもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64892318,"lng":138.31750592,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、延長40m","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0167","desc":"味噌蔵南から東に延びる折れ曲がり延長約４０ｍの塀で，桟瓦葺の小屋根を架けた真壁造。中途に塀中門，水車蔵南に桟瓦葺の棟門がつく。邸宅内の景観を整える構成要素で，旧主屋の北に広がる大庭園と，北辺に連続する各土蔵の入口部を隔てる役割を担っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003563"},{"id":"00003546","register_sub_id":"101","register_pk":"104536","name":"田中本家博物館おかる二階","kana":"たなかほんけはくぶつかんおかるにかい","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64848866,"lng":138.31766745,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積80㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0150","desc":"旧主屋台所部背面，角屋状に東へ突出したかたちで建つ。東西棟の切妻造，桟瓦葺，２階建で，東と北に幅広の下屋庇を設け，内部は２階に質の高いつくりの座敷を構える。基本は伝統的な土蔵造で，東面２階の横長窓や庇の持送り金具に洋風の影響がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003546"},{"id":"00003550","register_sub_id":"101","register_pk":"104540","name":"田中本家博物館表門","kana":"たなかほんけはくぶつかんおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64846093,"lng":138.31720238,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、間口10m","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0154","desc":"敷地西辺のやや南寄り，門土蔵と西之蔵の間に建つ。南北棟の切妻造，桟瓦葺で，桁行の南半分を棟門式の門口，北半分を真壁造の門番小屋とし，門口は湾曲した梁で棟木や桁を受ける独特の架構である。左右の土蔵ともよく調和がとれ，街路景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003550"},{"id":"00003559","register_sub_id":"101","register_pk":"104549","name":"田中本家博物館釜場蔵","kana":"たなかほんけはくぶつかんかまばぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.6483809,"lng":138.317505,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積56㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0163","desc":"籾土蔵の東に続く桁行約１１ｍの平屋建土蔵。東西棟の切妻造，桟瓦葺で，北面に扉口を設け，吹放し下屋庇をつける。東の酒蔵との間は通路で，南に潜戸をつける。酒蔵と同じ和小屋で，大棟にある煙出しの越屋根が，酒造施設としての特色の一端を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003559"},{"id":"00003547","register_sub_id":"101","register_pk":"104537","name":"田中本家博物館客殿","kana":"たなかほんけはくぶつかんきゃくでん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64867656,"lng":138.31770538,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0151","desc":"旧主屋居住部の東方，渡廊下で接続する。東西に長い２階建，入母屋造，桟瓦葺で，軒下に小庇を廻す。銘木をふんだんに使った上質の数寄屋造で，細部から造作に至るまで精緻につくる。庭に対して開放的な外観が時代性を反映している。棟梁は須坂の原田寅吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003547"},{"id":"00003545","register_sub_id":"101","register_pk":"104535","name":"田中本家博物館旧主屋","kana":"たなかほんけはくぶつかんきゅうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64851642,"lng":138.31753507,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋一部2階建、瓦葺、建築面積200㎡","structure_material":"木造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0149","desc":"屋敷中央南よりに西面して建つ。北の東西棟で寄棟造，２階建の居住部と，南の南北棟で切妻造，正面下屋庇付平屋建の台所部を土間通路を介して接続する。屋根は桟瓦葺，外壁は１階漆喰塗，上部荒壁だが，豪商の中心建築らしい雄大な構えで，外観は変化に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003545"},{"id":"00003560","register_sub_id":"101","register_pk":"104550","name":"田中本家博物館酒蔵","kana":"たなかほんけはくぶつかんさけぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.648373,"lng":138.31772051,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積291㎡","structure_material":"土蔵造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0164","desc":"敷地南辺のほぼ中央にある酒造施設で，寛政２年火災後の建築。桁行約３１ｍと規模が大きく，東西棟の切妻造，桟瓦葺，基本は平屋建で，太い梁に細い束・貫を組んだ和小屋になる。外壁は荒壁，軒廻りや窓口などを漆喰塗とする。田中本家の土蔵群で最も古い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003560"},{"id":"00003556","register_sub_id":"101","register_pk":"104546","name":"田中本家博物館新土蔵","kana":"たなかほんけはくぶつかんしんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64895204,"lng":138.31744176,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0160","desc":"敷地北辺，味噌蔵の東に建つ桁行約１４ｍの２階建土蔵。東西棟の切妻造，桟瓦葺，外壁はすべて漆喰塗で，北と南の腰を簓子下見板張とする。小屋は棟通りに立つ柱で太い化粧棟木を受け，これより厚板を桁に架け渡す。こうした架構は文庫蔵などと共通している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003556"},{"id":"00003557","register_sub_id":"101","register_pk":"104547","name":"田中本家博物館水車蔵","kana":"たなかほんけはくぶつかんすいしゃぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.6490179,"lng":138.317673,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積103㎡","structure_material":"土蔵造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0161","desc":"敷地北辺のほぼ中央に建つ桁行約２２．５ｍの土蔵。東西棟の切妻造，桟瓦葺で，外壁はすべて白漆喰塗，北と南の腰を簓子下見板張とする。内部は３室にわかれ，西室が中２階建，ほかは平屋建で，東室の内部では，引き込んだ水路を利用して水車を廻していた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003557"},{"id":"00003553","register_sub_id":"101","register_pk":"104543","name":"田中本家博物館隅土蔵","kana":"たなかほんけはくぶつかんすみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64882938,"lng":138.31704628,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0157","desc":"屋敷の北西隅にある平屋建の土蔵。南北棟の寄棟造・桟瓦葺で，街路側の外壁は白漆喰塗で腰を簓子下見板張で覆い，丁寧に縁取りした小窓を備える。南妻は西之蔵に接続し，東面の北半に文庫蔵の壁面が入り込むかたちになり，角地の隙間をよく整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003553"},{"id":"00003549","register_sub_id":"101","register_pk":"104539","name":"田中本家博物館中二階","kana":"たなかほんけはくぶつかんちゅうにかい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64853556,"lng":138.31783452,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積43㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0153","desc":"南北に長い２階建，切妻造，桟瓦葺で，客殿南方に建つが，もとは客殿の場所にあった。内部は１階が土間であるが，２階は床の間を備えた８畳の座敷２室とし，東面と西面には高欄付の縁と小庇を設けるなど，庭園における点景としての軽快な造形になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003549"},{"id":"00003552","register_sub_id":"101","register_pk":"104542","name":"田中本家博物館西之蔵","kana":"たなかほんけはくぶつかんにしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64864624,"lng":138.31713273,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積124㎡","structure_material":"土蔵造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0156","desc":"ほぼ同大の土蔵３棟が南北に並び，その間を低い屋根で繋ぎ，全体が南北約３５ｍの規模になる。各土蔵は桁行約９ｍの切妻造，桟瓦葺で，家財道具等を収納した。その間は細工場や検査場などに用いられた。豪農の屋敷正面に相応しい重厚な景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003552"},{"id":"00003561","register_sub_id":"101","register_pk":"104551","name":"田中本家博物館蓮池蔵","kana":"たなかほんけはくぶつかんはすいけぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64847442,"lng":138.318054,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積153㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0165","desc":"酒蔵の東に連続し，敷地東辺に至る桁行約２８ｍの平屋建土蔵で，名称はこの地にあった蓮池にちなむといわれている。東西棟の切妻造，桟瓦葺で，北面に吹放し下屋庇を設け，内部は同大の３室にわかれる。農業道具等の格納用で，大規模屋敷の生活を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003561"},{"id":"00003564","register_sub_id":"101","register_pk":"104554","name":"田中本家博物館東及び北土塀","kana":"たなかほんけはくぶつかんひがしおよびきたどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64883133,"lng":138.31806825,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、延長80m","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0168","desc":"敷地の東辺と北辺東側にあり，折れ曲がり延長約８０ｍの規模を有する。梁間２．３ｍで，桟瓦葺屋根を架け，敷地内側は吹放し，外側は漆喰塗とし，要所に仕切り壁を設け，収納にも用いる。大規模屋敷に欠かせない施設であり，また屋敷後方の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003564"},{"id":"00003562","register_sub_id":"101","register_pk":"104552","name":"田中本家博物館東土蔵","kana":"たなかほんけはくぶつかんひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64858124,"lng":138.31814428,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0166","desc":"屋敷の東南隅にある桁行約１２ｍの土蔵で，防火性や塀との連続性を考慮し，西面は荒壁，東面は漆喰壁を軒裏まで塗り込める。南北棟の切妻造，桟瓦葺で，西面に吹放し下屋庇を設ける。板戸を多く入れて広くとった西面の開口部に，もと馬小屋らしい特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003562"},{"id":"00003554","register_sub_id":"101","register_pk":"104544","name":"田中本家博物館文庫蔵","kana":"たなかほんけはくぶつかんぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64885472,"lng":138.31713655,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造3階建、瓦葺、建築面積80㎡","structure_material":"土蔵造3階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0158","desc":"敷地北西，桁行１４．５ｍの３階建土蔵。東西棟の桟瓦葺で，西が入母屋造，東が切妻造になる。外壁は白漆喰塗で，北面腰を簓子下見板張，南面の１階を荒壁，２階と３階の窓は土塗扉付とする。化粧棟木に厚板を架けた構法から江戸末期の建築と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003554"},{"id":"00003555","register_sub_id":"101","register_pk":"104545","name":"田中本家博物館味噌蔵","kana":"たなかほんけはくぶつかんみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64890452,"lng":138.31726735,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積34㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0159","desc":"敷地北辺，文庫蔵の東に建ち並ぶ桁行約１０ｍの平屋建土蔵。東西棟の切妻造，桟瓦葺で，北側面が白漆喰塗に腰簓子下見板張，南側面を荒壁とする。東端の新土蔵との境は通路とし，北側に潜戸を設ける。大規模な屋敷には欠かせない構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003555"},{"id":"00003558","register_sub_id":"101","register_pk":"104548","name":"田中本家博物館籾土蔵","kana":"たなかほんけはくぶつかんもみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64833559,"lng":138.31735524,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積108㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0162","desc":"桁行約１４ｍの平屋建土蔵で，東妻は釜場蔵，吹放し下屋庇を設けた北面西端に門土蔵が接する。東西棟の切妻造，桟瓦葺で，内部は２室にわかれ，穀物等を収納した。外壁は丁寧な漆喰塗で，腰を簓子下見板張で覆う。屋敷南西隅で，角地の景観を際だたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003558"},{"id":"00003551","register_sub_id":"101","register_pk":"104541","name":"田中本家博物館門土蔵","kana":"たなかほんけはくぶつかんもんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64837617,"lng":138.31725142,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積44㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0155","desc":"敷地西辺の街路に沿って建つ桁行約１０ｍの平屋建の土蔵。南北棟の切妻造，桟瓦葺で，南妻は籾土蔵と，北妻は表門とそれぞれ接する。外壁は丁寧な漆喰塗で，街路側の腰を簓子下見板張で覆う。表門や籾土蔵とよく調和しており，屋敷正面の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003551"},{"id":"00003548","register_sub_id":"101","register_pk":"104538","name":"田中本家博物館湯殿","kana":"たなかほんけはくぶつかんゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県須坂市大字小山476他","lat":36.64875418,"lng":138.31784252,"geo_status":"db","era":"明治28頃","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0152","desc":"客殿の東隣にあり，客殿と同時期の建築と思われる。東西棟の入母屋造，桟瓦葺で，南面に下屋庇を付ける。小規模な建物だが，平面は浴室と４畳半の小座敷の２室構成で，南半間を縁とする。真壁造の簡素な外観だが，木舞打の軒廻りなど，つくりは丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003548"},{"id":"00015448","register_sub_id":"101","register_pk":"533463","name":"東福寺檀信徒会館（旧滝沢家住宅主屋）","kana":"とうふくじだんしんとかいかん（きゅうたきざわけじゅうたくおもや）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上田市上塩尻字北側11-1","lat":36.41938611,"lng":138.21595556,"geo_status":"db","era":"江戸後期／安政3年（1856）頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積190㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"20 - 0671","desc":"北国街道沿いの集落に位置し、かつて蚕種業を営んだ農家の主屋。木造平屋建、寄棟造茅葺（鉄板仮葺）の東西棟で東面の屋根を切り上げる。東を土間、西を3列6室、北西を上座敷とする。土間上に部屋を設けて蚕室とするなど、当地域の養蚕の発展を伝える民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015448"},{"id":"00012364","register_sub_id":"101","register_pk":"531688","name":"土佐屋原家住宅主屋","kana":"とさやはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県下伊那郡阿智村清内路2395","lat":35.50674444,"lng":137.68032222,"geo_status":"db","era":"江戸末期／明治後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"20-527","desc":"山間の上清内路集落にあり、南面して建つ。二階建の本棟造民家で、三間四方の広いデイ回りに居室を配する。上手の奥座敷を入母屋の角屋で張出し、床･棚･付書院を備えるなど定型と異なる特徴を示す。集落内の古例となる住宅で、脇本陣としての格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012364"},{"id":"00005848","register_sub_id":"101","register_pk":"106834","name":"長澤家住宅土蔵","kana":"ながさわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代459","lat":36.561745,"lng":138.19635,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0273","desc":"街路に南面する敷地北寄りに建つ土蔵造２階建で，桁行４間，梁間２間半，切妻造，桟瓦葺の南北棟である。南妻に瓦葺庇下に戸口を設けて塗戸を釣り込む。北妻に２間半幅の土蔵造下屋を付けて米蔵，味噌蔵としている。外壁は白漆喰仕上げで，腰は下見板張である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005848"},{"id":"00005436","register_sub_id":"101","register_pk":"106424","name":"中村家住宅裏土蔵","kana":"なかむらけじゅうたくうらどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市三郷温2517-2","lat":36.24987423,"lng":137.88711608,"geo_status":"db","era":"江戸末期／明治20移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積42㎡","structure_material":"土蔵造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"20 － 0257","desc":"敷地北西隅に建ち，桁行４間，梁間２間半の規模で，土蔵造平屋建，切妻造，桟瓦葺とする。東面に奥行１間の瓦葺きの下屋を架け，北半を味噌蔵とし，南半に戸口を開く。外壁は中塗仕上げで，軒下まで塗り込める。味噌蔵付属の土蔵形式は中信地方に多くみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005436"},{"id":"00005435","register_sub_id":"101","register_pk":"106423","name":"中村家住宅表土蔵","kana":"なかむらけじゅうたくおもてどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市三郷温2517-2","lat":36.24974591,"lng":137.88743881,"geo_status":"db","era":"文政3","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"20 － 0256","desc":"主屋前の表庭の南側に建ち，桁行３間，梁間２間半の規模で，土蔵造２階建，切妻造，桟瓦葺，置屋根形式とする。内部を板壁とし，小屋に牛梁，登り梁を使う。外壁は中塗り仕上げで，２階妻側に窓を開く。西側を引戸で開き，北側に庇を架けて戸口を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005435"},{"id":"00015189","register_sub_id":"101","register_pk":"530613","name":"中村家住宅主屋","kana":"なかむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県北安曇郡小谷村大字千国字柳瀬乙10490","lat":36.77585556,"lng":137.90986111,"geo_status":"db","era":"江戸末期／明治前期・平成4年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積235㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0665","desc":"ＪＲ南小谷駅北東の高台に西面して建つ農家の主屋。桁行一一間、梁間五間、寄棟造茅葺(鉄板仮葺)で棟に越屋根を設け、西・北面に下屋を付す。内部北半に土間と旧マヤ、南半は床上で続き座敷に床と付書院を備える。高台に建つ姿が地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015189"},{"id":"00005434","register_sub_id":"101","register_pk":"106422","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市三郷温2517-2","lat":36.24978203,"lng":137.88727088,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積243㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"20 － 0255","desc":"敷地の中央やや西側に東面して建ち，桁行８間半，梁間７間半の規模で，木造平屋建，切妻造，桟瓦葺で，妻入の本棟造の形式をとる。間取りは北に土間をとり，奥を台所とし，南側に９坪のオエを中心に６間を並べる。差鴨居を比較的多く用い，江戸後期の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005434"},{"id":"00015190","register_sub_id":"101","register_pk":"530614","name":"中村家住宅土蔵","kana":"なかむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県北安曇郡小谷村大字千国字柳瀬乙10490","lat":36.77569167,"lng":137.90976111,"geo_status":"db","era":"明治36年／昭和14年頃・同中期改修","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積42㎡","structure_material":"木造平屋一部2階建","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0666","desc":"主屋の南側に並列して建つ家財蔵。二階建切妻造平入、置屋根形式で、正面に下屋を付す。外壁は石造風目地を入れたモルタル塗仕上で、腰下見板張とし、二階正面に掛子塗扉を吊る。各階一室で一階は土間、二階は板敷。主屋とともに集落の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015190"},{"id":"00005437","register_sub_id":"101","register_pk":"106425","name":"中村家住宅納屋","kana":"なかむらけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市三郷温2517-2","lat":36.24991127,"lng":137.88725856,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"20 － 0258","desc":"敷地北辺に近接して建ち，桁行６間半，梁間２間半の規模で，木造平屋建，切妻造，桟瓦葺とする。南側に庇を架け，その他三方及び軒下を塗り込める。内部は３室に分けられ，柱間に板を落とし込む。養蚕や精米に使われた。近代の防火を考えた納屋の形式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005437"},{"id":"00005438","register_sub_id":"101","register_pk":"106426","name":"中村家住宅門及び塀","kana":"なかむらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県安曇野市三郷温2517-2","lat":36.25212524,"lng":137.88894039,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"門 木造、鉄板葺、間口1.2m、塀 木造、鉄板葺、延長4.4m","structure_material":"門 木造","registered":"2006.03.27(平成18.03.27)","register_no":"20 － 0259","desc":"主屋と表土蔵をつないで建ち，門は間口１．２ｍ規模の棟門で，切妻造，鉄板葺で，塀は門の両側に延べ１．７ｍが付属し，さらに表土蔵までは高塀２．７ｍとし，腰を竪板張りとする。主屋前庭と中庭を区切る門と塀は中信地方の本棟造に付属して多くみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005438"},{"id":"00006620","register_sub_id":"101","register_pk":"107603","name":"成澤家住宅主屋","kana":"なるさわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代1462-1","lat":36.557068,"lng":138.20288886,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0328","desc":"敷地の西寄りに建ち、南に池を配する。建築面積１０８㎡、木造平屋建、桟瓦葺で、２棟の続き座敷を雁行型に接続し、周囲に縁を廻す。道路側を切妻造屋根、庭側の屋根を寄棟造とする。真田藩主の館である花の丸御殿の局屋敷を移築したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006620"},{"id":"00006677","register_sub_id":"101","register_pk":"107660","name":"西山家住宅主屋","kana":"にしやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代字中町664他","lat":36.565968,"lng":138.201721,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0321","desc":"明治２４年の大火後に再建された主屋で、通りに西面して建つ。桁行８間梁間５間、切妻造桟瓦葺、平入２階建の町家。１階には揚げ戸が残り、２階は白漆喰で塗り込め、大きめの窓を連続させる。旧松代城下における町家建築の形態をとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006677"},{"id":"00005847","register_sub_id":"101","register_pk":"106833","name":"野中家住宅主屋","kana":"のなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代1517","lat":36.560726,"lng":138.19574,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積242㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0278","desc":"松代城下，夏目小路に北面する敷地の北西寄りに建つ。桁行９間半，梁間６間半規模の木造つし２階建の寄棟造，桟瓦葺である。北面中央に式台を構え，居室は座敷１０畳他３室を食違いに配す。東妻に４畳半の茶室が突出する。旧武家住宅の威厳ある外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005847"},{"id":"00006623","register_sub_id":"101","register_pk":"107606","name":"長谷川家住宅表門","kana":"はせがわけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代1486-1","lat":36.55733176,"lng":138.19854938,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0331","desc":"主屋の式台玄関正面に建つ、切妻造桟瓦葺の腕木門。間口３．０ｍで、中央に門口１．５ｍの引分戸を開く。両脇の小脇壁を竪板張とし、両端から漆喰壁腰下見板張の袖塀が矩折れに延びる。装飾のない落ち着いた意匠で、武家の標準的な表門の形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006623"},{"id":"00006621","register_sub_id":"101","register_pk":"107604","name":"長谷川家住宅主屋","kana":"はせがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代1486-1","lat":36.55733576,"lng":138.19840365,"geo_status":"db","era":"明治前期／明治中期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0329","desc":"敷地中央東寄りに建ち、南に池を配する。建築面積１５１㎡の木造平屋建で、寄棟造桟瓦葺とする。３棟から構成され、中央棟は８畳２室と続きの間からなる。西棟の隠居所が後に増築された。穏やかな外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006621"},{"id":"00006622","register_sub_id":"101","register_pk":"107605","name":"長谷川家住宅土蔵","kana":"はせがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代1486-1","lat":36.5571422,"lng":138.19859149,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"20 － 0330","desc":"敷地東辺の南寄りに建つ。桁行３間梁間２間、土蔵造２階建。切妻造桟瓦葺で、西面に土庇をつける。丁寧に積んだ石積基礎上に建ち、外壁は鉢巻まで漆喰仕上げとし、通り側の腰部を下見板張とする。質実な外観が周囲の旧武家町の景観に調和する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006622"},{"id":"00001705","register_sub_id":"101","register_pk":"102695","name":"波多腰家住宅表門","kana":"はたこしけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市波田6492","lat":36.18772439,"lng":137.85576765,"geo_status":"db","era":"昭和期","year":1957,"year_source":"estimated","year_min":1926,"year_max":1988,"year_label":"昭和期","structure":"木造、冠木門、間口4m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0043","desc":"波多腰家は代々庄屋を務めた旧家であり、昭和６年の家相図に画かれた屋敷構を良く伝える。表門は西面する屋敷の正面に位置し、門柱２本の上部を貫で繋いだ冠木門の形式をとる。斜め後方に控柱を立てて支え、門の左右に塀が接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001705"},{"id":"00001703","register_sub_id":"101","register_pk":"102693","name":"波多腰家住宅蔵","kana":"はたこしけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市波田6492","lat":36.18800314,"lng":137.85608051,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0041","desc":"主屋の東北方、納屋の東に隣接して建つ二階建の土蔵。東西に棟を向けて南面し、間口は三間半とする。屋根は置屋根形式で切妻造、桟瓦葺とし、正面に下屋庇を設ける。地棟木銘があり、先代周次郎が起工し弥六の代に竣功した旨を記す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001703"},{"id":"00001699","register_sub_id":"101","register_pk":"102689","name":"波多腰家住宅米蔵","kana":"はたこしけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市波田6492","lat":36.18788835,"lng":137.85578259,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積93㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0037","desc":"主屋の北側に位置して東西に建ち並ぶ倉庫群のひとつ。桁行７間、梁間３間、二階建の大規模な土蔵で、腰壁は亀甲目地の瓦張とする。屋根は置屋根形式の切妻造とし、正面に塗籠の下屋を設ける。質の高い土蔵造で、地棟木銘により建築年代が明らか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001699"},{"id":"00001698","register_sub_id":"101","register_pk":"102688","name":"波多腰家住宅主屋","kana":"はたこしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市波田6492","lat":36.18775287,"lng":137.85602283,"geo_status":"db","era":"18世紀中期","year":1750,"year_source":"estimated","year_min":1731,"year_max":1770,"year_label":"18世紀中期","structure":"木造2階建、板葺、建築面積314㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0036","desc":"切妻造の大屋根を架け、西妻を正面として式台と大戸口を構える。正面妻壁に左右対称に出格子を構え、棟には雀踊りを飾るなど整った意匠からなる本棟造の好例。現在地に移ったと伝える寛延元年（１７４８）頃の建築で、背後に接続する離れは江戸末期の増築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001698"},{"id":"00001707","register_sub_id":"101","register_pk":"102697","name":"波多腰家住宅中門","kana":"はたこしけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市波田6492","lat":36.18762525,"lng":137.85593565,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、間口2m、板塀付","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0045","desc":"主屋の正面、式台と上手座敷との境から前方に延びて、主屋正面の前庭と座敷の庭を画す塀に開く門。棟門の形式で両開の板戸を構える。屋根は切妻造、桟瓦葺とする。瓦葺の屋根を備えた両袖塀とともに庭の景観を構成する重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001707"},{"id":"00001701","register_sub_id":"101","register_pk":"102691","name":"波多腰家住宅納屋","kana":"はたこしけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市波田6492","lat":36.18797873,"lng":137.8559919,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0039","desc":"米蔵の東に隣接する間口九間の長大な東西棟。柱を一間毎に立て並べ、貫を五段に通した成の高い平屋で、屋根は切妻造、桟瓦葺とする。内部は三間毎に間仕切り土間床の納屋三室を並べる。南正面は各室の西端間を入口とし、他の二間は腰壁を縦板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001701"},{"id":"00001702","register_sub_id":"101","register_pk":"102692","name":"波多腰家住宅灰屋","kana":"はたこしけじゅうたくはいや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県松本市波田6492","lat":36.18777673,"lng":137.85581272,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0040","desc":"表門を入った左手に位置する南北棟で、味噌藏と矩折れに建つ。間口三間半、奥行二間で、屋根は切妻造、桟瓦葺とする。西面して、南端一間分は柱と貫を現した真壁造とし、戸口を挟んだ北側は大壁造で腰廻りを石積みとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001702"},{"id":"00001704","register_sub_id":"101","register_pk":"102694","name":"波多腰家住宅文庫蔵","kana":"はたこしけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市波田6492","lat":36.18780435,"lng":137.85618896,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0042","desc":"主屋の背後に位置し、中庭を挟んで主屋と向かい合わせに西面して建つ。切石の土台上に建つ二階建の土蔵で、外壁は漆喰塗で腰廻りを海鼠壁とする。屋根は置屋根形式の切妻造、桟瓦葺とする。両妻の二階窓を華やかに縁取り、窓上に屋号の紋を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001704"},{"id":"00001700","register_sub_id":"101","register_pk":"102690","name":"波多腰家住宅味噌蔵","kana":"はたこしけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市波田6492","lat":36.18785598,"lng":137.85567572,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0038","desc":"米蔵の西に隣接する間口二間、奥行二間半の小規模な土蔵で、東西棟の東妻を入口とする。大壁造の外壁の一部に現在下見板を張る。内部は中二階を設ける。屋根は近年取り替えているが旧来の置屋根形式を守る。倉庫群の角地に位置し景観上重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001700"},{"id":"00001708","register_sub_id":"101","register_pk":"102698","name":"波多腰家住宅南門","kana":"はたこしけじゅうたくみなみもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市波田6492","lat":36.18750638,"lng":137.85642978,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、冠木門、間口2m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0046","desc":"波多腰家は約２千坪に及ぶ宅地の西面、北面及び東面の一部を屋敷林が取り囲み、南面は小道に面して腰板張りの塀が続く。南門は南面東寄りに位置する通用門で、門の形式は表門と同様に門柱２本の上部を貫で繋いだ冠木門で、内開きの板戸を構える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001708"},{"id":"00001706","register_sub_id":"101","register_pk":"102696","name":"波多腰家住宅門","kana":"はたこしけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市波田6492","lat":36.18782263,"lng":137.85587227,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、間口2m、板塀付","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"20 － 0044","desc":"主屋正面の前庭部分と、主屋西北方の倉庫群とを画す塀に開く門。背後に控柱を持つ棟門の形式で、屋根は切妻造、桟瓦葺とする。軸部は比較的成が高く、両開の格子戸を構える。瓦葺の屋根を備えた両袖塀とともに庭内の景観を構成する重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001706"},{"id":"00005142","register_sub_id":"101","register_pk":"106132","name":"八田家住宅大土蔵","kana":"はったけじゅうたくおおどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代577","lat":36.56272439,"lng":138.20262359,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0210","desc":"主屋の東に建つ。桁行７間，梁間４間の規模で，切妻造，桟瓦葺の土蔵造２階建。外壁は白漆喰仕上げの上を鉄板で覆う。開口部は正面南側妻壁のみに設け，１階を両開戸，２階を片開窓とし，それぞれ庇を張出す。豪商の屋敷後方の蔵の並ぶ景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005142"},{"id":"00005146","register_sub_id":"101","register_pk":"106136","name":"八田家住宅表門","kana":"はったけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代577","lat":36.56247866,"lng":138.20224786,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、瓦葺、間口7.0m","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0214","desc":"主屋の南に道路から後退して建つ。切妻造，桟瓦葺の腕木門で，太い門柱を用い，冠木上に鏡板を嵌め，下にはまぐさを差して両開戸を設ける。両脇に切妻屋根を置く袖塀が取付き，さらに上部に忍び返しを付けた羽目板張の塀が延び，豪商の屋敷の表構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005146"},{"id":"00005141","register_sub_id":"101","register_pk":"106131","name":"八田家住宅主屋","kana":"はったけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代577","lat":36.56256418,"lng":138.20234455,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積273㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0209","desc":"敷地の西部に接道して建つ。木造二階建で，東西棟の背部が南に突き出す矩折の平面を有し，桟瓦葺の屋根は道路側を寄棟とし，東側を切妻とする。真壁造で，外壁は白漆喰で仕上げる。１階に堅格子，２階に出格子を嵌めた意匠が商家らしい外観を作り上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005141"},{"id":"00005143","register_sub_id":"101","register_pk":"106133","name":"八田家住宅土蔵","kana":"はったけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代577","lat":36.56269987,"lng":138.20255545,"geo_status":"db","era":"明治30頃／昭和57曳家","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0211","desc":"敷地中央付近に南面して建つ。桁行５間，梁間２間半規模の土蔵造２階建。南北棟の切妻造，桟瓦葺屋根を置き，正面入口上部に庇を差し掛ける。外壁は白漆喰仕上げで，東面平壁には各階それぞれ２つの窓を設ける。かつては呉服屋土蔵と呼ばれた屋敷の構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005143"},{"id":"00005144","register_sub_id":"101","register_pk":"106134","name":"八田家住宅長土蔵","kana":"はったけじゅうたくながどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代577","lat":36.56277187,"lng":138.20234714,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積132㎡","structure_material":"土蔵造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0212","desc":"敷地北西隅から東西棟で延びる桁行２０間，梁間２間規模の土蔵造平屋建。屋根は切妻造桟瓦葺。敷地北側の外構を兼ね，道路に面して簡素な揚窓を一つ見せるだけの簡素なつくりで，外壁は中塗仕上げ。表門，主屋，塀と並んで豪商らしい屋敷の表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005144"},{"id":"00005145","register_sub_id":"101","register_pk":"106135","name":"八田家住宅塀","kana":"はったけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代577","lat":36.56277812,"lng":138.20255753,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、瓦葺、延長9.0m","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0213","desc":"敷地西側の道路に面し，主屋と長土蔵をつなぐ。長さ５間で，切妻造桟瓦葺屋根を置く。９段の簓子下見板を腰高に張り，その上を白漆喰で仕上げる。基礎には柴石を用い，石造りの排水口を設ける。整った意匠で，屋敷正面の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005145"},{"id":"00005160","register_sub_id":"101","register_pk":"106150","name":"馬場家住宅長屋門","kana":"ばばけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代1513","lat":36.56090738,"lng":138.19650128,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積37㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0228","desc":"街路に西面して建つ長屋門で，桁行７間半，梁間２間の平屋建，茅葺で，現在は金属板の仮葺とする。両開きの門扉脇に潜戸を設ける。門北側に２間，南側に土間の物入を設ける。真壁造の白漆喰仕上げで，腰を押縁下見板張とする。武家町の規模の大きな長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005160"},{"id":"00001350","register_sub_id":"101","register_pk":"102340","name":"原田家住宅主屋","kana":"はらだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市大字入山辺字南方582","lat":36.227016,"lng":138.017731,"geo_status":"db","era":"明治42頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積151㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"20 － 0023","desc":"急斜面に沿って開けた集落の中に位置し，東面して建つ。総２階建て，切妻造，桟瓦葺の本屋の周囲に庇を巡らす。蚕室を備えた成の高い２階，柱と貫を著した白漆喰塗りの外観など，当地域が養蚕業で栄えた当時の民家の姿を良く伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001350"},{"id":"00008278","register_sub_id":"101","register_pk":"133920","name":"原山家住宅表門","kana":"はらやまけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字馬場町1422-1","lat":36.55902972,"lng":138.19999511,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0361","desc":"仲間部屋の北に位置する。間口３．６ｍの薬医門。切妻造桟瓦葺。北側０．９ｍ、南側０．６ｍを袖壁とし、中央に両開戸を吊り、北袖壁に潜りを開く。袖壁上部は漆喰仕上げ。本柱控柱間にも漆喰仕上げの腰壁を設ける。武家屋敷の佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008278"},{"id":"00008277","register_sub_id":"101","register_pk":"133919","name":"原山家住宅仲間部屋","kana":"はらやまけじゅうたくちゅうげんべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字馬場町1422-1","lat":36.55893418,"lng":138.19998078,"geo_status":"db","era":"江戸後期／平成13年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0360","desc":"通りに東面する敷地の東辺中央に位置する。南北棟の切妻造桟瓦葺、木造２階建で、南面から西面にかけて深い下屋をまわす。外壁は大壁造で中塗仕上げとし、通り側には三つの窓に開け、平格子や出格子、肘掛手摺などを付け、単調な外観に表情を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008277"},{"id":"00008279","register_sub_id":"101","register_pk":"133921","name":"原山家住宅塀","kana":"はらやまけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字馬場町1422-1","lat":36.55909183,"lng":138.19998317,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土塀、瓦葺、延長12m","structure_material":"土塀","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0362","desc":"敷地東辺の表門から北を限る塀。高さ１．８ｍで、延長１２ｍに及ぶ。柱間１．２ｍに方柱を建て、通り側を中塗仕上げの大壁、敷地内部を真壁とし、貫をあらわす。屋根を桟瓦葺とし、腕木で支持する。仲間部屋や表門と一体となり、武家町の趣を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008279"},{"id":"00005872","register_sub_id":"101","register_pk":"106858","name":"はりこし亭","kana":"はりこしてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県小諸市乙字城下1208-7他","lat":36.322182,"lng":138.417252,"geo_status":"db","era":"明治元／平成14移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、鉄板葺一部瓦葺、建築面積356㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0299","desc":"南北に長い敷地の東側に建ち，桁行９間，梁間７間半の規模で，木造平屋建，切妻造，鉄板葺とする。南側を通り土間や厨房とし，北側を床上部とし，６室を２列に並べ，室内は欅材を多く使う。２階正面に袖卯建を，棟に越屋根を上げる。元は瓦葺きの町家であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005872"},{"id":"00009164","register_sub_id":"101","register_pk":"164717","name":"東飯田酒造店松の間","kana":"ひがしいいだしゅぞうてんまつのま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市篠ノ井小松原1724","lat":36.61992147,"lng":138.13310657,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地中央に建ち、桁行9.3メートル梁間8.2メートル、木造平屋建、寄棟造妻入桟瓦葺である。北面玄関に、起りをもたせた切妻の庇を設け、壁には松に鶴の鏝絵を飾る。内部は座敷飾りを備えた21畳座敷を中心とし、良質な松材で普請する、造酒屋の接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009164"},{"id":"00005135","register_sub_id":"101","register_pk":"106125","name":"日暮し庵鎮守社","kana":"ひぐらしあんちんじゅしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市松代町松代190","lat":36.56343713,"lng":138.19888552,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造、鉄板葺、3棟","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0203","desc":"敷地南東隅に西面して建ち，覆屋の中に北から稲荷社，伊勢社，秋葉社の３棟が並ぶ。稲荷社，秋葉社は一間社流造，伊勢社は神明造であり，いずれも屋根はトタン葺である。鎮守社を祀る近世武家屋敷の風習を伝え，屋敷地の歴史的景観を構成する要素として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005135"},{"id":"00005134","register_sub_id":"101","register_pk":"106124","name":"日暮し庵店舗","kana":"ひぐらしあんてんぽ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代190","lat":36.56360614,"lng":138.19865162,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積151㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0202","desc":"敷地北西部に道路より後退して建つ。桁行６間，梁間４間規模，入母屋造の木造平屋建。南面及び北面に下屋をかける。当初は茅葺であった屋根に，現在は鉄板を被せる。西面，北面に増築があるが，外観は近世武家屋敷の面影をよく伝え，殿町の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005134"},{"id":"00012149","register_sub_id":"101","register_pk":"352948","name":"平林家住宅主屋","kana":"ひらばやしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県塩尻市大字広丘原新田字新田166-1","lat":36.151513,"lng":137.947952,"geo_status":"db","era":"江戸末期／平成8年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積182㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"20-520","desc":"街道沿いに敷地を構え、西面して建つ。間口一六メートル、奥行一三メートル、切妻造妻入。床上部はもと二列四室で、式台玄関から下座敷、上座敷の構えがよく残る。破風板上に棟飾りの雀踊りを戴く伝統的な本棟造の外観で、街路からの良好な屋敷構えを形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012149"},{"id":"00012361","register_sub_id":"101","register_pk":"531685","name":"平林家住宅主屋","kana":"ひらばやしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市大字笹賀5063","lat":36.19181667,"lng":137.94232222,"geo_status":"db","era":"明治前期／昭和中期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、金属板葺、建築面積230㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"20-524","desc":"松本市郊外の農村にある、いわゆる本棟造の民家。間口の広い切妻造妻入で、右手を土間、左手を二列三室の床上部とする。前方には式台付の座敷と上座敷を並べ、後方に内向きの居室を並べる。雀踊りや出格子など表構えも充実し、当地の上層農家の典型を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012361"},{"id":"00011956","register_sub_id":"101","register_pk":"211100","name":"平林家住宅主屋","kana":"ひらばやしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県大町市大町2572-1","lat":36.504155,"lng":137.860327,"geo_status":"db","era":"明治23年／昭和57年改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積313㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"20 - 0515","desc":"大町の中心部に位置し、通りに南面する。間口七間、土蔵造二階建で、式台玄関や座敷棟を備えた上層町家の典型を示す。明治二二年の大火後の再建で、立石清重の設計により、防火や耐火の対策が講じられた大町最初の土蔵造町家として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011956"},{"id":"00011957","register_sub_id":"101","register_pk":"211101","name":"平林家住宅文庫蔵・塩蔵・漬物蔵","kana":"ひらばやしけじゅうたくぶんこくら・しおぐら・つけものぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県大町市大町2572-1","lat":36.504467,"lng":137.860158,"geo_status":"db","era":"江戸後期／安政6年（1859）改修、明治2年増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積186㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"20 - 0516","desc":"主屋の北側に建つ。梁間三間で、桁行五間の文庫蔵に、桁行各四間の漬物蔵と塩蔵を増築し、置屋根形式で切妻造の屋根を架け、東正面に下屋庇を付ける。文庫蔵は中央に九寸角の棟持柱を立て、内壁を竪板張とした堅牢な蔵で、漬物蔵、塩蔵とともに繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011957"},{"id":"00009010","register_sub_id":"101","register_pk":"162370","name":"平松家住宅北土蔵","kana":"ひらまつけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上高井郡小布施町大字小布施1947","lat":36.70193981,"lng":138.30963471,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0407","desc":"主屋の北側に東西棟で建つ。土蔵造二階建、桁行５．６ｍ梁間３．７ｍ、切妻造、置屋根式の桟瓦葺とする。漆喰仕上げで腰壁を板張とし、東面の出入口に庇を付け、西面に鏝細工の家紋を飾る。鉢巻や窓まわりを丁寧に仕上げた重厚な外観をもつ土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009010"},{"id":"00009012","register_sub_id":"101","register_pk":"162372","name":"平松家住宅車屋（旧水車小屋）","kana":"ひらまつけじゅうたくくるまや（きゅうすいしゃごや）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県上高井郡小布施町大字小布施1947","lat":36.70161774,"lng":138.30932547,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0409","desc":"屋敷地南面の道路沿いに位置し、南土蔵の西隣に建つ。木造平屋建、桁行５．３ｍ梁間３．０ｍ、切妻造桟瓦葺である。中塗仕上げで、北面の屋根を葺降ろして下屋とし出入口を開く。蚕室、南土蔵と軒を並べて建ち、道路沿いの歴史的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009012"},{"id":"00009013","register_sub_id":"101","register_pk":"162373","name":"平松家住宅蚕室","kana":"ひらまつけじゅうたくさんしつ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県上高井郡小布施町大字小布施1947","lat":36.70158053,"lng":138.30960135,"geo_status":"db","era":"明治後期／大正期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積172㎡、門塀付","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0410","desc":"屋敷地の東南隅に北面して建つ。木造二階建、桁行１０．９ｍ梁間４．５ｍと桁行１２．８ｍ梁間５．５ｍの二棟からなり、各々切妻造桟瓦葺で越屋根を上げる。建ちが高く、開口を大きくとるなど独特の形態で、養蚕の興隆を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009013"},{"id":"00009008","register_sub_id":"101","register_pk":"162368","name":"平松家住宅主屋","kana":"ひらまつけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上高井郡小布施町大字小布施1947","lat":36.70177429,"lng":138.30966294,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）及び瓦葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0405","desc":"小布施町郊外の敷地中央に南面して建つ。木造平屋建、桁行２３．４ｍ梁間８．８ｍ、寄棟造茅葺（鉄板仮葺）の主体部の東側に入母屋造桟瓦葺の棟が取り付く。四間取を基本に、玄関や座敷など接客空間を充実させた平面になり、民家の発展過程を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009008"},{"id":"00009009","register_sub_id":"101","register_pk":"162369","name":"平松家住宅小座敷","kana":"ひらまつけじゅうたくしょうざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県上高井郡小布施町大字小布施1947","lat":36.70171269,"lng":138.30953848,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0406","desc":"主屋の南側に建ち、渡廊下を介して接続する。桁行３．７ｍル梁間４．０ｍ、木造平屋建、切妻造桟瓦葺で、北面に下屋を張出す。トコと地袋を備え、炉を切り、舟底天井とするなど丁寧なつくりになる。大正期における農家の生活の一端を伝える接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009009"}];
